package store

import (
	"context"
	"fmt"
)

func (p *Postgres) Search(ctx context.Context, query string) ([]SearchResult, error) {
	if query == "" {
		return nil, nil
	}
	rows, err := p.db.Query(ctx, `
		SELECT 'question' AS kind, q.id, q.title,
		       ts_headline('english', q.body_markdown, plainto_tsquery('english', $1),
		                   'MaxWords=20, MinWords=5, StartSel=, StopSel=') AS excerpt,
		       COALESCE((SELECT array_agg(t.name) FROM question_tags qt JOIN tags t ON t.id=qt.tag_id WHERE qt.question_id=q.id), '{}'),
		       ts_rank(q.search_vector, plainto_tsquery('english', $1))::float8 AS rank,
		       q.created_at
		FROM questions q
		WHERE q.search_vector @@ plainto_tsquery('english', $1) AND q.is_deleted=FALSE

		UNION ALL

		SELECT 'article' AS kind, a.id, a.title,
		       ts_headline('english', a.body_markdown, plainto_tsquery('english', $1),
		                   'MaxWords=20, MinWords=5, StartSel=, StopSel=') AS excerpt,
		       COALESCE((SELECT array_agg(t.name) FROM article_tags at JOIN tags t ON t.id=at.tag_id WHERE at.article_id=a.id), '{}'),
		       ts_rank(a.search_vector, plainto_tsquery('english', $1))::float8 AS rank,
		       a.created_at
		FROM articles a
		WHERE a.search_vector @@ plainto_tsquery('english', $1)

		ORDER BY rank DESC
		LIMIT 50`, query)
	if err != nil {
		return nil, fmt.Errorf("search: %w", err)
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.Kind, &r.ID, &r.Title, &r.Excerpt, &r.Tags, &r.Score, &r.CreatedAt); err != nil {
			return nil, fmt.Errorf("scan search result: %w", err)
		}
		results = append(results, r)
	}
	return results, rows.Err()
}

