package main

import (
	"context"
	"log/slog"
	"os"

	"github.com/immuta/heapoverflow/internal/db"
	"github.com/immuta/heapoverflow/internal/importer"
	"github.com/immuta/heapoverflow/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stdout, nil))

	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		log.Error("DATABASE_URL is required")
		os.Exit(1)
	}
	dataDir := os.Getenv("DATA_DIR")
	if dataDir == "" {
		dataDir = "./data"
	}

	ctx := context.Background()
	pool, err := db.Connect(ctx, databaseURL)
	if err != nil {
		log.Error("connect to database", "err", err)
		os.Exit(1)
	}
	defer pool.Close()

	imp := importer.New(store.New(pool), dataDir, log)
	if err := imp.Run(ctx); err != nil {
		log.Error("import failed", "err", err)
		os.Exit(1)
	}
}
