package auth

import (
	"context"
	"net/http"

	"github.com/immuta/heapoverflow/internal/store"
)

// StaticProvider authenticates as a fixed user from the database.
// Used for local development when AUTH_MODE=static.
type StaticProvider struct {
	store store.Store
	email string
}

func NewStaticProvider(s store.Store, email string) *StaticProvider {
	return &StaticProvider{store: s, email: email}
}

func (p *StaticProvider) LoginURL(state string) string {
	return "/api/v1/auth/static-login"
}

func (p *StaticProvider) HandleCallback(ctx context.Context, r *http.Request) (*store.User, error) {
	// Look up or create the static dev user
	u, err := p.store.GetUserByEmail(ctx, p.email)
	if err == nil {
		return u, nil
	}
	// Create if not found
	return p.store.CreateUser(ctx, store.CreateUserParams{
		DisplayName: "Dev User",
		Email:       &p.email,
	})
}
