// UnmarshalJSON accepts either a unix-seconds integer or a string in
// time.RFC3339 / "2006-01-02T15:04:05.000" form. The SO Teams export mixes
// the two — older creation_date fields are unix ints, while some
// last_activity_date fields are ISO strings.
func (u *unixTime) UnmarshalJSON(b []byte) error {
	if string(b) == "null" {
		return nil
	}
	if len(b) > 0 && b[0] == '"' {
		var s string
		if err := json.Unmarshal(b, &s); err != nil {
			return err
		}
		layouts := []string{
			time.RFC3339Nano,
			time.RFC3339,
			"2006-01-02T15:04:05.999999999",
			"2006-01-02T15:04:05",
		}
		var lastErr error
		for _, layout := range layouts {
			if t, err := time.Parse(layout, s); err == nil {
				u.Time = t.UTC()
				return nil
			} else {
				lastErr = err
			}
		}
		return lastErr
	}
	var ts int64
	if err := json.Unmarshal(b, &ts); err != nil {
		return err
	}
	u.Time = time.Unix(ts, 0).UTC()
	return nil
}

