package api

import (
	"net/http"
	"strconv"

	"github.com/go-playground/validator/v10"
	"github.com/immuta/heapoverflow/internal/auth"
	"github.com/immuta/heapoverflow/internal/markdown"
	"github.com/immuta/heapoverflow/internal/store"
)

var validate = validator.New()

type createQuestionRequest struct {
	Title        string   `json:"title" validate:"required,min=10,max=300"`
	BodyMarkdown string   `json:"body_markdown" validate:"required,min=20"`
	Tags         []string `json:"tags" validate:"max=5"`
}

type voteRequest struct {
	VoteType int `json:"vote_type" validate:"required,oneof=-1 1"`
}

func (h *Handler) handleListQuestions(w http.ResponseWriter, r *http.Request) {
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	questions, total, err := h.store.ListQuestions(r.Context(), store.ListQuestionsParams{
		Page:    page,
		PerPage: 20,
		Sort:    r.URL.Query().Get("sort"),
		Tag:     r.URL.Query().Get("tag"),
		Query:   r.URL.Query().Get("q"),
	})
	if err != nil {
		h.log.Error("list questions", "err", err)
		writeError(w, http.StatusInternalServerError, "failed to list questions")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"questions": questions, "total": total})
}

func (h *Handler) handleGetQuestion(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	q, err := h.store.GetQuestion(r.Context(), id)
	if err != nil {
		writeError(w, http.StatusNotFound, "question not found")
		return
	}
	answers, _ := h.store.ListAnswersByQuestion(r.Context(), id)
	for _, a := range answers {
		a.Comments, _ = h.store.ListCommentsByPost(r.Context(), a.ID, "answer")
	}
	q.Answers = answers
	q.Comments, _ = h.store.ListCommentsByPost(r.Context(), id, "question")
	go h.store.IncrementQuestionViewCount(r.Context(), id) //nolint:errcheck
	writeJSON(w, http.StatusOK, q)
}

func (h *Handler) handleCreateQuestion(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFromContext(r.Context())
	var req createQuestionRequest
