package api

import (
	"net/http"

	"github.com/immuta/heapoverflow/internal/auth"
)

func (h *Handler) handleAuthLogin(w http.ResponseWriter, r *http.Request) {
	state, err := auth.GenerateState()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "state generation failed")
		return
	}
	http.Redirect(w, r, h.auth.LoginURL(state), http.StatusFound)
}

func (h *Handler) handleAuthCallback(w http.ResponseWriter, r *http.Request) {
	u, err := h.auth.HandleCallback(r.Context(), r)
	if err != nil {
		h.log.Error("auth callback", "err", err)
		http.Redirect(w, r, "/login?error=auth_failed", http.StatusFound)
		return
	}
	if err := h.sessions.SetSession(w, r, u.ID); err != nil {
		writeError(w, http.StatusInternalServerError, "session error")
		return
	}
	http.Redirect(w, r, "/auth/callback", http.StatusFound)
}

func (h *Handler) handleAuthStaticLogin(w http.ResponseWriter, r *http.Request) {
	u, err := h.auth.HandleCallback(r.Context(), r)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "static login failed")
		return
	}
	if err := h.sessions.SetSession(w, r, u.ID); err != nil {
		writeError(w, http.StatusInternalServerError, "session error")
		return
	}
	http.Redirect(w, r, "/", http.StatusFound)
}

func (h *Handler) handleAuthLogout(w http.ResponseWriter, r *http.Request) {
	h.sessions.ClearSession(w, r)
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

func (h *Handler) handleAuthMe(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFromContext(r.Context())
	if u == nil {
		writeError(w, http.StatusUnauthorized, "not authenticated")
		return
	}
	writeJSON(w, http.StatusOK, u)
}

package api

import (
	"net/http"
	"strconv"

	"github.com/go-playground/validator/v10"

	"github.com/immuta/heapoverflow/internal/auth"
	"github.com/immuta/heapoverflow/internal/markdown"
	"github.com/immuta/heapoverflow/internal/store"
)

var validate = validator.New()

type createQuestionRequest struct {
	Title        string   `json:"title" validate:"required,min=10,max=300"`
	BodyMarkdown string   `json:"body_markdown" validate:"required,min=20"`
	Tags         []string `json:"tags" validate:"max=5"`
}

type voteRequest struct {
	VoteType int `json:"vote_type" validate:"oneof=-1 0 1"`
}

func (h *Handler) handleListQuestions(w http.ResponseWriter, r *http.Request) {
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	questions, total, err := h.store.ListQuestions(r.Context(), store.ListQuestionsParams{
		Page:    page,
		PerPage: 20,
		Sort:    r.URL.Query().Get("sort"),
		Tag:     r.URL.Query().Get("tag"),
		Query:   r.URL.Query().Get("q"),
	})
	if err != nil {
		h.log.Error("list questions", "err", err)
		writeError(w, http.StatusInternalServerError, "failed to list questions")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"questions": questions, "total": total})
}

func (h *Handler) handleGetQuestion(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	q, err := h.store.GetQuestion(r.Context(), id)
	if err != nil {
		writeError(w, http.StatusNotFound, "question not found")
		return
	}
	answers, _ := h.store.ListAnswersByQuestion(r.Context(), id)
	for _, a := range answers {
		a.Comments, _ = h.store.ListCommentsByPost(r.Context(), a.ID, "answer")
	}
	q.Answers = answers
	q.Comments, _ = h.store.ListCommentsByPost(r.Context(), id, "question")
	go func() { _ = h.store.IncrementQuestionViewCount(r.Context(), id) }()
	writeJSON(w, http.StatusOK, q)
}

func (h *Handler) handleCreateQuestion(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFromContext(r.Context())
	var req createQuestionRequest
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if err := validate.Struct(req); err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}
	bodyHTML, err := markdown.Render(req.BodyMarkdown)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "markdown render failed")
		return
	}
	q, err := h.store.CreateQuestion(r.Context(), store.CreateQuestionParams{
		UserID:       u.ID,
		Title:        req.Title,
		BodyMarkdown: req.BodyMarkdown,
		BodyHTML:     bodyHTML,
		Tags:         req.Tags,
	})
	if err != nil {
		h.log.Error("create question", "err", err)
		writeError(w, http.StatusInternalServerError, "failed to create question")
		return
	}
	writeJSON(w, http.StatusCreated, q)
}

func (h *Handler) handleUpdateQuestion(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFromContext(r.Context())
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid id")
		return
	}
	existing, err := h.store.GetQuestion(r.Context(), id)
	if err != nil {
		writeError(w, http.StatusNotFound, "question not found")
		return
	}
	if existing.UserID != u.ID {
		writeError(w, http.StatusForbidden, "not your question")
		return
	}
	var req createQuestionRequest
	if err := readJSON(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if err := validate.Struct(req); err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}
	bodyHTML, _ := markdown.Render(req.BodyMarkdown)
	q, err := h.store.UpdateQuestion(r.Context(), store.UpdateQuestionParams{
		ID:           id,
		Title:        req.Title,
		BodyMarkdown: req.BodyMarkdown,
		BodyHTML:     bodyHTML,
		Tags:         req.Tags,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "update failed")
