import { provideHttpClient, withInterceptors } from '@angular/common/http';
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideAnimations } from '@angular/platform-browser/animations';
import { provideRouter, withComponentInputBinding } from '@angular/router';

import { authInterceptor } from './auth/auth.interceptor';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideAnimations(),
    provideRouter(routes, withComponentInputBinding()),
    provideHttpClient(withInterceptors([authInterceptor])),
  ],
};

import { Routes } from '@angular/router';
import { authGuard } from './auth/auth.guard';

export const routes: Routes = [
  { path: 'login', loadComponent: () => import('./auth/login/login.component').then((m) => m.LoginComponent) },
  {
    path: 'auth/callback',
    loadComponent: () => import('./auth/callback/auth-callback.component').then((m) => m.AuthCallbackComponent),
  },
  {
    path: '',
    canActivate: [authGuard],
    loadComponent: () => import('./shell/shell.component').then((m) => m.ShellComponent),
    children: [
      { path: '', pathMatch: 'full', redirectTo: 'questions' },
      {
        path: 'questions',
        loadComponent: () => import('./questions/list/question-list.component').then((m) => m.QuestionListComponent),
      },
      {
        path: 'questions/ask',
        loadComponent: () => import('./questions/ask/ask-question.component').then((m) => m.AskQuestionComponent),
      },
      {
        path: 'questions/:id',
        loadComponent: () =>
          import('./questions/detail/question-detail.component').then((m) => m.QuestionDetailComponent),
      },
      { path: 'tags', loadComponent: () => import('./tags/list/tag-list.component').then((m) => m.TagListComponent) },
      {
        path: 'tags/:name',
        loadComponent: () => import('./tags/detail/tag-detail.component').then((m) => m.TagDetailComponent),
      },
      {
        path: 'articles',
        loadComponent: () => import('./articles/list/article-list.component').then((m) => m.ArticleListComponent),
      },
      {
        path: 'articles/:id',
        loadComponent: () =>
          import('./articles/detail/article-detail.component').then((m) => m.ArticleDetailComponent),
      },
      {
        path: 'users/:id',
        loadComponent: () => import('./users/profile/user-profile.component').then((m) => m.UserProfileComponent),
      },
      { path: 'search', loadComponent: () => import('./search/search.component').then((m) => m.SearchComponent) },
    ],
  },
  { path: '**', redirectTo: '' },
];

