import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { AuthService } from '../auth/auth.service';

@Component({
  selector: 'app-shell',
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive, FormsModule],
  template: `
    <div class="shell">
      <aside class="nav">
        <div class="brand">
          <span class="logo">⚡</span>
          <span>HeapOverflow</span>
        </div>
        <nav>
          <a routerLink="/questions" routerLinkActive="active">Questions</a>
          <a routerLink="/questions/ask" routerLinkActive="active">Ask</a>
          <a routerLink="/tags" routerLinkActive="active">Tags</a>
          <a routerLink="/articles" routerLinkActive="active">Articles</a>
        </nav>
        @if (auth.user(); as u) {
        <div class="me">
          <a [routerLink]="['/users', u.ID]">
            @if (u.ProfileImage) {
              <img [src]="u.ProfileImage" alt="" />
            } @else {
              <span class="avatar-placeholder">{{ u.DisplayName.charAt(0) }}</span>
            }
            <span>{{ u.DisplayName }}</span>
          </a>
          <button class="logout" (click)="auth.logout()">Sign out</button>
        </div>
        }
      </aside>
      <main>
        <header class="topbar">
          <form (submit)="doSearch($event)">
            <input
              type="search"
              placeholder="Search questions and articles…"
              [(ngModel)]="searchQuery"
              name="q"
            />
          </form>
        </header>
        <section class="content">
          <router-outlet />
        </section>
      </main>
    </div>
  `,
  styles: [`
    :host { display: block; height: 100vh; }
    .shell { display: grid; grid-template-columns: 240px 1fr; height: 100%; }
    .nav {
      background: #fff;
      border-right: 1px solid #d0d7de;
      display: flex; flex-direction: column;
      padding: 1.25rem 1rem;
      gap: 1rem;
    }
    .brand { display: flex; align-items: center; gap: .5rem; font-weight: 700; font-size: 1.1rem; }
    .logo { font-size: 1.4rem; }
    nav { display: flex; flex-direction: column; gap: .25rem; flex: 1; }
    nav a {
      display: block; padding: .5rem .75rem; border-radius: 6px;
      color: #1f2328; text-decoration: none; font-weight: 500;
    }
    nav a:hover { background: #f3f4f6; text-decoration: none; }
    nav a.active { background: #ddf4ff; color: #0969da; }
    .me { display: flex; flex-direction: column; gap: .5rem; padding-top: .75rem; border-top: 1px solid #eef1f4; }
    .me a { display: flex; align-items: center; gap: .5rem; color: inherit; text-decoration: none; }
    .me img, .avatar-placeholder { width: 28px; height: 28px; border-radius: 50%; background: #d0d7de; display: inline-flex; align-items: center; justify-content: center; font-weight: 700; font-size: 13px; color: #fff; }
    .logout { font-size: 12px; background: none; border: 0; color: #57606a; cursor: pointer; text-align: left; padding: 0 0 0 36px; }
    .logout:hover { color: #cf222e; text-decoration: underline; }

    main { display: flex; flex-direction: column; min-width: 0; }
    .topbar { padding: .75rem 1.5rem; background: #fff; border-bottom: 1px solid #d0d7de; }
    .topbar form { max-width: 480px; }
    .content { padding: 1.5rem; overflow-y: auto; flex: 1; }
  `],
})
export class ShellComponent {
  auth = inject(AuthService);
  private router = inject(Router);
  searchQuery = '';

  doSearch(e: Event) {
    e.preventDefault();
    const q = this.searchQuery.trim();
    if (q) this.router.navigate(['/search'], { queryParams: { q } });
  }
}

