import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { Question } from '../../models';

@Component({
  selector: 'app-question-list',
  standalone: true,
  imports: [CommonModule, RouterLink, DatePipe],
  template: `
    <header class="head">
      <h1>Questions</h1>
      <a routerLink="/questions/ask" class="btn primary">Ask question</a>
    </header>

    <div class="tabs">
      @for (s of sorts; track s.id) {
        <button
          class="tab"
          [class.active]="sort() === s.id"
          (click)="setSort(s.id)">{{ s.label }}</button>
      }
    </div>

    @if (loading()) {
      <p class="muted">Loading…</p>
    } @else if (error()) {
      <p class="error">{{ error() }}</p>
    } @else if (!questions().length) {
      <p>No questions yet.</p>
    } @else {
      <ul class="cards">
        @for (q of questions(); track q.ID) {
          <li class="card">
            <div class="stats">
              <span><strong>{{ q.Score }}</strong> votes</span>
              <span [class.answered]="q.IsAnswered">
                <strong>{{ q.Answers?.length || 0 }}</strong> answers
              </span>
              <span><strong>{{ q.ViewCount }}</strong> views</span>
            </div>
            <div class="body">
              <a class="title" [routerLink]="['/questions', q.ID]">{{ q.Title }}</a>
              <div class="tags">
                @for (t of q.Tags; track t) {
                  <a class="tag-chip" [routerLink]="['/tags', t]">{{ t }}</a>
                }
              </div>
              <div class="meta muted">
                asked {{ q.CreatedAt | date:'mediumDate' }}
                @if (q.Owner) { by <a [routerLink]="['/users', q.Owner.ID]">{{ q.Owner.DisplayName }}</a> }
              </div>
            </div>
          </li>
        }
      </ul>

      <nav class="pager">
        <button class="btn" [disabled]="page() <= 1" (click)="setPage(page() - 1)">‹ Prev</button>
        <span class="muted">Page {{ page() }} of {{ totalPages() }} ({{ total() }} total)</span>
        <button class="btn" [disabled]="page() >= totalPages()" (click)="setPage(page() + 1)">Next ›</button>
      </nav>
    }
  `,
  styles: [`
    .head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
    h1 { margin: 0; }
    .tabs { display: flex; gap: .25rem; margin-bottom: 1rem; border-bottom: 1px solid #d0d7de; }
    .tab { background: none; border: 0; padding: .5rem 1rem; cursor: pointer; font-size: 14px; color: #57606a; border-bottom: 2px solid transparent; }
    .tab:hover { color: #1f2328; }
    .tab.active { color: #1f2328; border-bottom-color: #1f6feb; font-weight: 600; }
    .cards { list-style: none; padding: 0; margin: 0; }
    .card { display: grid; grid-template-columns: 120px 1fr; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #eef1f4; }
    .stats { display: flex; flex-direction: column; gap: .25rem; color: #57606a; font-size: 13px; text-align: right; }
    .stats .answered { color: #1a7f37; font-weight: 600; }
    .title { font-size: 17px; font-weight: 500; }
    .tags { margin: .35rem 0; }
    .meta { margin-top: .25rem; }
    .pager { display: flex; justify-content: center; align-items: center; gap: 1rem; margin-top: 1.5rem; }
    .error { color: #cf222e; }
  `],
})
export class QuestionListComponent implements OnInit {
  private api = inject(ApiService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);

  readonly sorts = [
    { id: 'newest', label: 'Newest' },
    { id: 'active', label: 'Active' },
    { id: 'votes', label: 'Votes' },
    { id: 'unanswered', label: 'Unanswered' },
  ];

  readonly questions = signal<Question[]>([]);
  readonly total = signal(0);
  readonly page = signal(1);
  readonly sort = signal('newest');
  readonly loading = signal(true);
  readonly error = signal('');
  readonly tag = signal<string | undefined>(undefined);
  readonly totalPages = () => Math.max(1, Math.ceil(this.total() / 20));

  ngOnInit() {
    this.route.queryParamMap.subscribe((qp) => {
      this.page.set(Number(qp.get('page') || '1'));
      this.sort.set(qp.get('sort') || 'newest');
      this.tag.set(qp.get('tag') || undefined);
      this.reload();
    });
  }

  setSort(s: string) {
    this.router.navigate([], { queryParams: { sort: s, page: 1, tag: this.tag() }, queryParamsHandling: 'merge' });
  }

  setPage(p: number) {
    this.router.navigate([], { queryParams: { page: p }, queryParamsHandling: 'merge' });
  }

  private reload() {
    this.loading.set(true);
    this.error.set('');
    this.api
      .listQuestions({ page: this.page(), sort: this.sort(), tag: this.tag() })
      .subscribe({
        next: (res) => {
          this.questions.set(res.questions || []);
          this.total.set(res.total);
          this.loading.set(false);
        },
        error: (err) => {
          this.error.set('Failed to load questions');
          this.loading.set(false);
          console.error(err);
        },
      });
  }
}

