import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { AuthService } from '../../auth/auth.service';
import { Answer, Comment, Question } from '../../models';

@Component({
  selector: 'app-question-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule, DatePipe],
  template: `
    @if (loading()) {
      <p class="muted">Loading…</p>
    } @else if (!q()) {
      <p>Question not found.</p>
    } @else {
      <article class="question">
        <h1>{{ q()!.Title }}</h1>
        <div class="muted">
          asked {{ q()!.CreatedAt | date:'medium' }}
          @if (q()!.Owner) { by <a [routerLink]="['/users', q()!.Owner!.ID]">{{ q()!.Owner!.DisplayName }}</a> }
          · {{ q()!.ViewCount }} views
        </div>

        <div class="post">
          <div class="vote">
            <button (click)="vote('question', q()!.ID, 1)">▲</button>
            <span>{{ q()!.Score }}</span>
            <button (click)="vote('question', q()!.ID, -1)">▼</button>
          </div>
          <div class="body">
            <div class="markdown-body" [innerHTML]="renderHTML(q()!.BodyHTML)"></div>
            <div class="tags">
              @for (t of q()!.Tags; track t) {
                <a class="tag-chip" [routerLink]="['/tags', t]">{{ t }}</a>
              }
            </div>
            @if (q()!.Comments?.length) {
              <ul class="comments">
                @for (c of q()!.Comments!; track c.ID) {
                  <li>
                    <span class="markdown-body" [innerHTML]="renderHTML(c.BodyHTML)"></span>
                    <span class="muted"> — {{ c.Owner?.DisplayName }} ({{ c.CreatedAt | date:'shortDate' }})</span>
                  </li>
                }
              </ul>
            }
            <form class="comment-form" (submit)="addQuestionComment($event)">
              <input type="text" [(ngModel)]="newQuestionComment" name="qc" placeholder="Add a comment (10+ chars)…" />
              <button class="btn" type="submit" [disabled]="newQuestionComment.length < 10">Comment</button>
            </form>
          </div>
        </div>

        <h2>{{ q()!.Answers?.length || 0 }} Answers</h2>
        @for (a of q()!.Answers || []; track a.ID) {
          <div class="post answer" [class.accepted]="a.IsAccepted">
            <div class="vote">
              <button (click)="vote('answer', a.ID, 1)">▲</button>
              <span>{{ a.Score }}</span>
              <button (click)="vote('answer', a.ID, -1)">▼</button>
              @if (a.IsAccepted) { <span class="accepted-icon" title="Accepted">✓</span> }
            </div>
            <div class="body">
              <div class="markdown-body" [innerHTML]="renderHTML(a.BodyHTML)"></div>
              <div class="muted">
                answered {{ a.CreatedAt | date:'medium' }}
                @if (a.Owner) { by <a [routerLink]="['/users', a.Owner.ID]">{{ a.Owner.DisplayName }}</a> }
              </div>
              @if (isQuestionOwner() && !a.IsAccepted) {
                <button class="btn" (click)="accept(a.ID)">Accept this answer</button>
              }
              @if (a.Comments?.length) {
                <ul class="comments">
                  @for (c of a.Comments!; track c.ID) {
                    <li>
                      <span class="markdown-body" [innerHTML]="renderHTML(c.BodyHTML)"></span>
                      <span class="muted"> — {{ c.Owner?.DisplayName }} ({{ c.CreatedAt | date:'shortDate' }})</span>
                    </li>
                  }
                </ul>
              }
              <form class="comment-form" (submit)="addAnswerComment($event, a)">
                <input type="text" [(ngModel)]="answerCommentText[a.ID]" [name]="'ac' + a.ID" placeholder="Add a comment…" />
                <button class="btn" type="submit" [disabled]="(answerCommentText[a.ID] || '').length < 10">Comment</button>
              </form>
            </div>
          </div>
        }

        <h2>Your Answer</h2>
        <form class="answer-form" (submit)="postAnswer($event)">
          <textarea [(ngModel)]="newAnswer" name="answer" placeholder="Write your answer in Markdown (min 20 chars)…" rows="8"></textarea>
          <button class="btn primary" type="submit" [disabled]="newAnswer.length < 20">Post answer</button>
        </form>
      </article>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .post { display: grid; grid-template-columns: 60px 1fr; gap: 1rem; padding: 1.5rem 0; border-bottom: 1px solid #eef1f4; }
    .post.answer.accepted { background: #f0f9ee; padding-left: 1rem; padding-right: 1rem; border-left: 4px solid #1a7f37; border-radius: 6px; }
    .vote { display: flex; flex-direction: column; align-items: center; gap: .25rem; font-weight: 600; }
    .vote button { background: none; border: 1px solid #d0d7de; border-radius: 6px; padding: .25rem .5rem; cursor: pointer; }
    .vote button:hover { background: #f3f4f6; }
    .accepted-icon { color: #1a7f37; font-size: 1.3rem; }
    .tags { margin-top: 1rem; }
    .comments { list-style: none; padding: .75rem 0 0; margin: 0; font-size: 13px; border-top: 1px solid #eef1f4; }
    .comments li { padding: .25rem 0; }
    .comment-form { display: flex; gap: .5rem; margin-top: .75rem; }
    .comment-form input { flex: 1; }
    .answer-form textarea { margin-bottom: .5rem; }
    h2 { margin: 1.5rem 0 .5rem; }
