@Component({
  selector: 'app-tag-list',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  template: `
    <h1>Tags</h1>
    <input type="search" [(ngModel)]="filter" (ngModelChange)="reload()" placeholder="Filter tags…" />
    <div class="grid">
      @for (t of tags(); track t.ID) {
        <a class="tag-card" [routerLink]="['/tags', t.Name]">
          <strong class="tag-chip">{{ t.Name }}</strong>
          <p class="muted">{{ t.Description || 'No description' }}</p>
          <div class="muted">{{ t.Count }} questions</div>
        </a>
      }
    </div>
  `,
  styles: [`
    h1 { margin-top: 0; }
    input { max-width: 320px; margin-bottom: 1rem; }
    .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; }
    .tag-card { display: block; padding: 1rem; border: 1px solid #d0d7de; border-radius: 6px; background: #fff; text-decoration: none; color: inherit; }
    .tag-card:hover { border-color: #1f6feb; text-decoration: none; }
    .tag-card p { margin: .5rem 0; min-height: 2.5em; }
  `],
})
export class TagListComponent implements OnInit {
  private api = inject(ApiService);
  readonly tags = signal<Tag[]>([]);
  filter = '';
  private debounce?: ReturnType<typeof setTimeout>;

  ngOnInit() {
    this.reload();
  }

  reload() {
    if (this.debounce) clearTimeout(this.debounce);
    this.debounce = setTimeout(() => {
      this.api.listTags(this.filter || undefined).subscribe({
        next: (res) => this.tags.set(res.tags || []),
      });
    }, 200);
  }
}

