import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { Question, Tag } from '../../models';

@Component({
  selector: 'app-tag-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, DatePipe],
  template: `
    @if (tag(); as t) {
      <header>
        <h1><span class="tag-chip">{{ t.Name }}</span></h1>
        @if (t.Description) { <p>{{ t.Description }}</p> }
        @if (t.SMEs?.length) {
          <p class="muted">
            SMEs:
            @for (u of t.SMEs!; track u.ID; let last = $last) {
              <a [routerLink]="['/users', u.ID]">{{ u.DisplayName }}</a>{{ last ? '' : ', ' }}
            }
          </p>
        }
      </header>
      <h2>Questions tagged "{{ t.Name }}"</h2>
      @if (questions().length === 0) {
        <p class="muted">No questions yet.</p>
      } @else {
        <ul class="list">
          @for (q of questions(); track q.ID) {
            <li>
              <a [routerLink]="['/questions', q.ID]">{{ q.Title }}</a>
              <span class="muted">— {{ q.Score }} votes · {{ q.CreatedAt | date:'mediumDate' }}</span>
            </li>
          }
        </ul>
      }
    } @else if (loading()) {
      <p class="muted">Loading…</p>
    } @else {
      <p>Tag not found.</p>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .list { list-style: none; padding: 0; }
    .list li { padding: .5rem 0; border-bottom: 1px solid #eef1f4; }
  `],
})
export class TagDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(ApiService);

  readonly tag = signal<Tag | null>(null);
  readonly questions = signal<Question[]>([]);
  readonly loading = signal(true);

  ngOnInit() {
    this.route.paramMap.subscribe((p) => {
      const name = p.get('name');
      if (!name) return;
      this.loading.set(true);
      this.api.getTag(name).subscribe({
        next: (t) => {
          this.tag.set(t);
          this.loading.set(false);
        },
        error: () => {
          this.tag.set(null);
          this.loading.set(false);
        },
      });
      this.api.listQuestions({ tag: name, page: 1 }).subscribe({
        next: (res) => this.questions.set(res.questions || []),
      });
    });
  }
}

