import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { Article } from '../../models';

@Component({
  selector: 'app-article-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, DatePipe],
  template: `
    @if (article(); as a) {
      <article>
        <h1>{{ a.Title }}</h1>
        <p class="muted">
          {{ a.CreatedAt | date:'medium' }}
          @if (a.Owner) { by <a [routerLink]="['/users', a.Owner.ID]">{{ a.Owner.DisplayName }}</a> }
        </p>
        <div class="tags">
          @for (t of a.Tags; track t) {
            <a class="tag-chip" [routerLink]="['/tags', t]">{{ t }}</a>
          }
        </div>
        <div class="markdown-body" [innerHTML]="renderHTML(a.BodyHTML)"></div>
      </article>
    } @else if (loading()) {
      <p class="muted">Loading…</p>
    } @else {
      <p>Article not found.</p>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .tags { margin: 1rem 0; }
  `],
})
export class ArticleDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(ApiService);
  private sanitizer = inject(DomSanitizer);
  readonly article = signal<Article | null>(null);
  readonly loading = signal(true);

  ngOnInit() {
    this.route.paramMap.subscribe((p) => {
      const id = Number(p.get('id'));
      if (!id) return;
      this.loading.set(true);
      this.api.getArticle(id).subscribe({
        next: (a) => {
          this.article.set(a);
          this.loading.set(false);
        },
        error: () => {
          this.article.set(null);
          this.loading.set(false);
        },
      });
    });
  }

  renderHTML(html: string): SafeHtml {
    return this.sanitizer.bypassSecurityTrustHtml(html);
  }
}

