// Package uploads handles user-uploaded media: content-addressed storage on
// disk, mime+size validation, and an HTTP file server for serving them.
package uploads

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// MaxImageBytes caps a single upload at 5 MiB.
const MaxImageBytes = 5 << 20

// allowedMIME maps detected content type to a canonical file extension.
var allowedMIME = map[string]string{
	"image/png":  ".png",
	"image/jpeg": ".jpg",
	"image/gif":  ".gif",
	"image/webp": ".webp",
}

// Store persists uploaded files to a directory using content-addressed names
// (sha256 of the file body). Names look like "deadbeef…cafe.png".
type Store struct {
	Dir string
}

// New returns a Store rooted at dir, creating the directory if absent.
func New(dir string) (*Store, error) {
	if dir == "" {
		return nil, errors.New("upload dir is empty")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("create upload dir: %w", err)
	}
	return &Store{Dir: dir}, nil
}

// SaveResult describes a stored upload.
type SaveResult struct {
	Filename string // {sha256}.{ext}
	URL      string // /uploads/{filename}
	MIME     string
	Bytes    int64
}

// SaveBytes writes data to the store. If the same content already exists on
// disk the call is a no-op and the existing file is returned. The mime type
// is detected from the first 512 bytes to avoid trusting client-supplied
// headers.
func (s *Store) SaveBytes(data []byte) (*SaveResult, error) {
	if len(data) == 0 {
		return nil, errors.New("empty file")
	}
	if int64(len(data)) > MaxImageBytes {
		return nil, fmt.Errorf("file exceeds %d bytes", MaxImageBytes)
	}
	mime := http.DetectContentType(data[:min(len(data), 512)])
	mime = strings.SplitN(mime, ";", 2)[0]
	ext, ok := allowedMIME[mime]
	if !ok {
		return nil, fmt.Errorf("unsupported content type %q", mime)
	}
	sum := sha256.Sum256(data)
	name := hex.EncodeToString(sum[:]) + ext
	path := filepath.Join(s.Dir, name)
	if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
		if err := os.WriteFile(path, data, 0o644); err != nil {
			return nil, fmt.Errorf("write: %w", err)
		}
	} else if err != nil {
		return nil, fmt.Errorf("stat: %w", err)
	}
	return &SaveResult{
		Filename: name,
		URL:      "/uploads/" + name,
		MIME:     mime,
		Bytes:    int64(len(data)),
	}, nil
}

// SaveReader streams the upload through an in-memory buffer (capped at
// MaxImageBytes+1) then delegates to SaveBytes.
func (s *Store) SaveReader(r io.Reader) (*SaveResult, error) {
	limited := io.LimitReader(r, MaxImageBytes+1)
	data, err := io.ReadAll(limited)
	if err != nil {
		return nil, fmt.Errorf("read: %w", err)
	}
	return s.SaveBytes(data)
}

// FileServer returns an http.Handler that serves files from the store's
// directory under the given URL prefix (e.g. "/uploads/"). Missing files
// return 404; the handler is safe against path traversal because
// http.FileServer + http.Dir reject ".." components.
func (s *Store) FileServer(prefix string) http.Handler {
	return http.StripPrefix(prefix, http.FileServer(http.Dir(s.Dir)))
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

