package main

import (
	"context"
	"errors"
	"flag"
	"io/fs"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/immuta/heapoverflow/internal/api"
	"github.com/immuta/heapoverflow/internal/auth"
	"github.com/immuta/heapoverflow/internal/db"
	"github.com/immuta/heapoverflow/internal/store"
	"github.com/immuta/heapoverflow/ui"
)

func main() {
	migrateOnly := flag.Bool("migrate-only", false, "run migrations and exit")
	flag.Parse()

	log := slog.New(slog.NewTextHandler(os.Stdout, nil))

	cfg, err := loadConfig()
	if err != nil {
		log.Error("load config", "err", err)
		os.Exit(1)
	}

	log.Info("running database migrations")
	if err := runMigrations(cfg.DatabaseURL); err != nil {
		log.Error("migrate", "err", err)
		os.Exit(1)
	}

	if *migrateOnly {
		log.Info("migrations complete, exiting")
		return
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	pool, err := db.Connect(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Error("connect to database", "err", err)
		os.Exit(1)
	}
	defer pool.Close()

	s := store.New(pool)
	sessions := auth.NewSessionManager(s, cfg.SessionSecret, cfg.Env == "production")

	var provider auth.Provider
	if cfg.AuthMode == "okta" {
		provider, err = auth.NewOktaProvider(ctx, s,
			cfg.OktaIssuer, cfg.OktaClientID, cfg.OktaClientSecret, cfg.OktaRedirectURL)
		if err != nil {
			log.Error("init okta provider", "err", err)
			os.Exit(1)
		}
	} else {
		provider = auth.NewStaticProvider(s, "dev@heapoverflow.local")
	}

	h := api.NewHandler(s, sessions, provider, log)
	apiMux := h.Routes()

	distFS := ui.DistFS()
	uiSubFS, err := fs.Sub(distFS, ui.DistRoot)
	if err != nil {
		log.Error("embed ui", "err", err)
		os.Exit(1)
	}
	fileServer := http.FileServer(http.FS(uiSubFS))

	root := http.NewServeMux()
	root.Handle("/api/", apiMux)
	root.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if path == "/" {
			path = "/index.html"
		}
		clean := path[1:]
		if f, err := uiSubFS.Open(clean); err == nil {
			f.Close()
			fileServer.ServeHTTP(w, r)
			return
		}
		// Angular SPA: serve index.html for unknown paths so client-side
		// routing can take over.
		http.ServeFileFS(w, r, uiSubFS, "index.html")
	})

	handler := api.Logging(log)(root)

	srv := &http.Server{
		Addr:              ":" + cfg.Port,
		Handler:           handler,
		ReadHeaderTimeout: 10 * time.Second,
	}

	go func() {
		log.Info("server starting", "addr", srv.Addr, "auth_mode", cfg.AuthMode)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("server error", "err", err)
			stop()
		}
	}()

	<-ctx.Done()
	log.Info("shutdown signal received")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Error("graceful shutdown failed", "err", err)
	}
}

