import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import {
  Answer,
  Article,
  Comment,
  Question,
  QuestionsPage,
  SearchResult,
  Tag,
  User,
} from './models';

const BASE = '/api/v1';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);

  // Auth
  me(): Observable<User> {
    return this.http.get<User>(`${BASE}/auth/me`);
  }
  logout(): Observable<unknown> {
    return this.http.post(`${BASE}/auth/logout`, {});
  }

  // Questions
  listQuestions(params: {
    page?: number;
    sort?: string;
    tag?: string;
    q?: string;
  } = {}): Observable<QuestionsPage> {
    let p = new HttpParams();
    if (params.page) p = p.set('page', params.page);
    if (params.sort) p = p.set('sort', params.sort);
    if (params.tag) p = p.set('tag', params.tag);
    if (params.q) p = p.set('q', params.q);
    return this.http.get<QuestionsPage>(`${BASE}/questions`, { params: p });
  }
  getQuestion(id: number): Observable<Question> {
    return this.http.get<Question>(`${BASE}/questions/${id}`);
  }
  createQuestion(body: { title: string; body_markdown: string; tags: string[] }): Observable<Question> {
    return this.http.post<Question>(`${BASE}/questions`, body);
  }
  updateQuestion(id: number, body: { title: string; body_markdown: string; tags: string[] }): Observable<Question> {
    return this.http.put<Question>(`${BASE}/questions/${id}`, body);
  }
  deleteQuestion(id: number): Observable<unknown> {
    return this.http.delete(`${BASE}/questions/${id}`);
  }
  voteQuestion(id: number, voteType: -1 | 0 | 1): Observable<unknown> {
    return this.http.post(`${BASE}/questions/${id}/vote`, { vote_type: voteType });
  }

  // Answers
  createAnswer(questionId: number, body_markdown: string): Observable<Answer> {
    return this.http.post<Answer>(`${BASE}/questions/${questionId}/answers`, { body_markdown });
  }
  updateAnswer(id: number, body_markdown: string): Observable<Answer> {
    return this.http.put<Answer>(`${BASE}/answers/${id}`, { body_markdown });
  }
  deleteAnswer(id: number): Observable<unknown> {
    return this.http.delete(`${BASE}/answers/${id}`);
  }
  voteAnswer(id: number, voteType: -1 | 0 | 1): Observable<unknown> {
    return this.http.post(`${BASE}/answers/${id}/vote`, { vote_type: voteType });
  }
  acceptAnswer(id: number): Observable<unknown> {
    return this.http.post(`${BASE}/answers/${id}/accept`, {});
  }

  // Comments
  createQuestionComment(questionId: number, body_markdown: string): Observable<Comment> {
    return this.http.post<Comment>(`${BASE}/questions/${questionId}/comments`, { body_markdown });
  }
  createAnswerComment(answerId: number, body_markdown: string): Observable<Comment> {
    return this.http.post<Comment>(`${BASE}/answers/${answerId}/comments`, { body_markdown });
  }
  deleteComment(id: number): Observable<unknown> {
    return this.http.delete(`${BASE}/comments/${id}`);
  }

  // Tags
  listTags(q?: string): Observable<{ tags: Tag[] | null }> {
    let p = new HttpParams();
    if (q) p = p.set('q', q);
    return this.http.get<{ tags: Tag[] | null }>(`${BASE}/tags`, { params: p });
  }
  getTag(name: string): Observable<Tag> {
    return this.http.get<Tag>(`${BASE}/tags/${encodeURIComponent(name)}`);
  }

  // Users
  getUser(id: number): Observable<User> {
    return this.http.get<User>(`${BASE}/users/${id}`);
  }
  updateMe(body: { display_name: string; about_me: string | null }): Observable<User> {
    return this.http.put<User>(`${BASE}/users/me`, body);
  }

  // Articles
  listArticles(): Observable<{ articles: Article[] | null }> {
    return this.http.get<{ articles: Article[] | null }>(`${BASE}/articles`);
  }
  getArticle(id: number): Observable<Article> {
    return this.http.get<Article>(`${BASE}/articles/${id}`);
  }

  // Search
  search(q: string): Observable<{ results: SearchResult[] | null }> {
    const p = new HttpParams().set('q', q);
    return this.http.get<{ results: SearchResult[] | null }>(`${BASE}/search`, { params: p });
  }
}

