import { CommonModule } from '@angular/common';
import {
  Component,
  ElementRef,
  EventEmitter,
  Input,
  Output,
  ViewChild,
  forwardRef,
  inject,
  signal,
} from '@angular/core';
import { ControlValueAccessor, FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { ApiService } from '../api.service';

/**
 * MarkdownEditor wraps a textarea with image-upload affordances:
 *  - paste an image from the clipboard
 *  - drag-and-drop one or more image files
 *  - click the "Upload image" button to pick a file
 *
 * Each upload POSTs to /api/v1/uploads/image. On success it inserts an
 * `![](url)` reference at the current cursor position.
 *
 * Wires up as a ControlValueAccessor so it works with [(ngModel)] just like
 * a plain textarea would.
 */
@Component({
  selector: 'app-markdown-editor',
  standalone: true,
  imports: [CommonModule, FormsModule],
  providers: [
    { provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => MarkdownEditorComponent), multi: true },
  ],
  template: `
    <div class="editor" [class.dragover]="dragOver()">
      <textarea
        #ta
        [value]="value"
        (input)="onInput($event)"
        (paste)="onPaste($event)"
        (dragover)="onDragOver($event)"
        (dragleave)="onDragLeave($event)"
        (drop)="onDrop($event)"
        (blur)="onTouched()"
        [placeholder]="placeholder"
        [rows]="rows"
      ></textarea>
      <div class="toolbar">
        <button type="button" class="btn small" (click)="picker.click()" [disabled]="uploading()">
          @if (uploading()) { Uploading… } @else { 📎 Upload image }
        </button>
        <input
          #picker
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          multiple
          hidden
          (change)="onPick($event)"
        />
        @if (error()) { <span class="err">{{ error() }}</span> }
        <span class="hint">Markdown. Paste, drop, or click to upload images.</span>
      </div>
    </div>
  `,
  styles: [`
    :host { display: block; }
    .editor { position: relative; }
    .editor.dragover textarea { outline: 2px dashed #1f6feb; outline-offset: -4px; }
    textarea { width: 100%; }
    .toolbar { display: flex; align-items: center; gap: .75rem; margin-top: .35rem; font-size: 12px; }
    .btn.small { padding: .25rem .65rem; font-size: 12px; }
    .hint { color: #57606a; }
    .err { color: #cf222e; }
  `],
})
export class MarkdownEditorComponent implements ControlValueAccessor {
  @ViewChild('ta') taRef?: ElementRef<HTMLTextAreaElement>;

  @Input() placeholder = '';
  @Input() rows = 12;
  @Output() valueChange = new EventEmitter<string>();

  private api = inject(ApiService);

  value = '';
  readonly uploading = signal(false);
  readonly dragOver = signal(false);
  readonly error = signal('');

  private onChange: (v: string) => void = () => {};
  onTouched: () => void = () => {};

  // ControlValueAccessor
  writeValue(v: string): void {
    this.value = v ?? '';
  }
  registerOnChange(fn: (v: string) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  onInput(e: Event) {
    const v = (e.target as HTMLTextAreaElement).value;
    this.value = v;
    this.onChange(v);
    this.valueChange.emit(v);
  }

  onPaste(e: ClipboardEvent) {
    const items = e.clipboardData?.items;
    if (!items) return;
    const files: File[] = [];
    for (let i = 0; i < items.length; i++) {
      const it = items[i];
      if (it.kind === 'file' && it.type.startsWith('image/')) {
        const f = it.getAsFile();
        if (f) files.push(f);
      }
    }
    if (files.length > 0) {
      e.preventDefault();
      this.uploadAll(files);
    }
  }

  onDragOver(e: DragEvent) {
    e.preventDefault();
    this.dragOver.set(true);
  }
  onDragLeave(_: DragEvent) {
    this.dragOver.set(false);
  }
  onDrop(e: DragEvent) {
    e.preventDefault();
    this.dragOver.set(false);
    const files = Array.from(e.dataTransfer?.files || []).filter((f) => f.type.startsWith('image/'));
    if (files.length > 0) this.uploadAll(files);
  }
  onPick(e: Event) {
    const input = e.target as HTMLInputElement;
    const files = Array.from(input.files || []);
    input.value = '';
    if (files.length > 0) this.uploadAll(files);
  }

  private uploadAll(files: File[]) {
    this.error.set('');
    this.uploading.set(true);
    this.uploadSequential(files, 0);
  }

  private uploadSequential(files: File[], i: number) {
    if (i >= files.length) {
      this.uploading.set(false);
      return;
    }
    const f = files[i];
    this.api.uploadImage(f).subscribe({
      next: (res) => {
        this.insertAtCursor(`![${f.name || 'image'}](${res.url})`);
        this.uploadSequential(files, i + 1);
      },
      error: (err) => {
        this.error.set(err?.error?.error || 'Upload failed');
        this.uploading.set(false);
      },
    });
  }

  private insertAtCursor(snippet: string) {
    const ta = this.taRef?.nativeElement;
    if (!ta) {
      this.value = (this.value ? this.value + '\n\n' : '') + snippet + '\n';
      this.emit();
      return;
    }
    const start = ta.selectionStart ?? this.value.length;
    const end = ta.selectionEnd ?? this.value.length;
    // Add newlines around if not already on a fresh line.
    const before = this.value.slice(0, start);
    const after = this.value.slice(end);
    const prefix = before.length && !before.endsWith('\n') ? '\n\n' : '';
    const suffix = after.startsWith('\n') ? '\n' : '\n\n';
    const insert = prefix + snippet + suffix;
    this.value = before + insert + after;
    this.emit();
    // Re-focus and place cursor after the inserted snippet.
    queueMicrotask(() => {
      ta.focus();
      const pos = before.length + insert.length;
      ta.setSelectionRange(pos, pos);
    });
  }

  private emit() {
    this.onChange(this.value);
    this.valueChange.emit(this.value);
  }
}

