    .actions { display: flex; justify-content: flex-end; }
    .error { color: #cf222e; }
  `],
})
export class AskQuestionComponent {
  private api = inject(ApiService);
  private router = inject(Router);

  title = '';
  body = '';
  tagsRaw = '';
  readonly submitting = signal(false);
  readonly error = signal('');

  canSubmit() {
    return this.title.length >= 10 && this.body.length >= 20;
  }

  submit(e: Event) {
    e.preventDefault();
    if (!this.canSubmit()) return;
    const tags = this.tagsRaw
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean)
      .slice(0, 5);
    this.submitting.set(true);
    this.error.set('');
    this.api.createQuestion({ title: this.title, body_markdown: this.body, tags }).subscribe({
      next: (q) => this.router.navigate(['/questions', q.ID]),
      error: (err) => {
        this.error.set(typeof err?.error?.error === 'string' ? err.error.error : 'Failed to create question');
        this.submitting.set(false);
      },
    });
  }
}

