// mediarewrite scans existing posts for external image URLs (primarily the
// SO Teams CDN at stackoverflowteams.com/c/.../images/...), downloads each
// unique URL to the local upload store, and rewrites references in the
// body_markdown and body_html columns.
//
// Usage:
//
//	DATABASE_URL=postgres://...  UPLOAD_DIR=./uploads \
//	  [SO_TEAMS_COOKIE='ASP.NET_SessionId=...']  go run ./cmd/mediarewrite
//
// SO Teams image URLs require authentication; set SO_TEAMS_COOKIE to the
// raw Cookie header value from a logged-in browser session. Without it,
// the tool will best-effort fetch public URLs (e.g. i.stack.imgur.com) and
// skip private ones with a warning.
package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/immuta/heapoverflow/internal/db"
	"github.com/immuta/heapoverflow/internal/markdown"
	"github.com/immuta/heapoverflow/internal/uploads"
)

// urlPattern matches absolute http(s) URLs that look like image references.
// We intentionally cast a wide net here and filter by extension/content-type
// after fetching.
var urlPattern = regexp.MustCompile(
	`https?://[^\s)\]"'<>]+\.(?:png|jpg|jpeg|gif|webp)(?:\?[^\s)\]"'<>]*)?`,
)

// hostsRequiringCookie lists hostnames that need the SO Teams auth cookie.
// Other hosts are fetched without auth.
var hostsRequiringCookie = map[string]bool{
	"stackoverflowteams.com": true,
}

func main() {
	dry := flag.Bool("dry-run", false, "scan and report URLs without downloading or modifying the DB")
	flag.Parse()

	log := slog.New(slog.NewTextHandler(os.Stdout, nil))

	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		log.Error("DATABASE_URL is required")
		os.Exit(1)
	}
	uploadDir := os.Getenv("UPLOAD_DIR")
	if uploadDir == "" {
		uploadDir = "./uploads"
	}
	cookie := os.Getenv("SO_TEAMS_COOKIE")

	ctx := context.Background()
	pool, err := db.Connect(ctx, databaseURL)
	if err != nil {
		log.Error("connect db", "err", err)
		os.Exit(1)
	}
	defer pool.Close()

	store, err := uploads.New(uploadDir)
	if err != nil {
		log.Error("init upload store", "err", err)
		os.Exit(1)
	}

	r := &rewriter{
		log:    log,
		pool:   pool,
		store:  store,
		client: &http.Client{Timeout: 30 * time.Second},
		cookie: cookie,
		cache:  map[string]string{},
		dryRun: *dry,
	}

	if err := r.run(ctx); err != nil {
		log.Error("rewrite failed", "err", err)
		os.Exit(1)
	}
}

type rewriter struct {
	log    *slog.Logger
	pool   *pgxpool.Pool
	store  *uploads.Store
	client *http.Client
	cookie string
	cache  map[string]string // original URL -> local /uploads/{name} (or "" on fail)
	dryRun bool

	downloaded int
	skipped    int
	failed     int
}

type postRow struct {
	table        string
	id           int
	bodyMarkdown string
}

func (r *rewriter) run(ctx context.Context) error {
	for _, tbl := range []string{"questions", "answers", "comments", "articles"} {
		if err := r.processTable(ctx, tbl); err != nil {
			return fmt.Errorf("process %s: %w", tbl, err)
		}
	}
	r.log.Info("done",
		"downloaded", r.downloaded,
		"skipped", r.skipped,
		"failed", r.failed,
		"unique_urls", len(r.cache),
		"dry_run", r.dryRun,
	)
	return nil
}

func (r *rewriter) processTable(ctx context.Context, table string) error {
	q := fmt.Sprintf(
		`SELECT id, body_markdown FROM %s WHERE body_markdown ~ 'https?://[^[:space:]]+\.(png|jpg|jpeg|gif|webp)'`,
		table,
	)
	rows, err := r.pool.Query(ctx, q)
	if err != nil {
		return err
	}
	defer rows.Close()

	var posts []postRow
	for rows.Next() {
		var p postRow
		p.table = table
		if err := rows.Scan(&p.id, &p.bodyMarkdown); err != nil {
			return err
		}
		posts = append(posts, p)
	}
	if err := rows.Err(); err != nil {
		return err
	}
	r.log.Info("scanned", "table", table, "matched_posts", len(posts))

	for _, p := range posts {
		if err := r.rewritePost(ctx, p); err != nil {
			r.log.Warn("rewrite post failed", "table", p.table, "id", p.id, "err", err)
		}
	}
	return nil
}

func (r *rewriter) rewritePost(ctx context.Context, p postRow) error {
	matches := urlPattern.FindAllString(p.bodyMarkdown, -1)
	if len(matches) == 0 {
		return nil
	}

	// Deduplicate within a single post.
	seen := map[string]bool{}
	replacements := map[string]string{}
	for _, m := range matches {
		if seen[m] {
			continue
		}
		seen[m] = true
		local, err := r.fetchOrCached(ctx, m)
		if err != nil {
			r.log.Warn("fetch failed", "url", m, "err", err)
			r.failed++
			continue
		}
		if local == "" {
			// Cached negative result
			continue
		}
		replacements[m] = local
	}

	if len(replacements) == 0 {
		return nil
	}

	newMD := p.bodyMarkdown
	for orig, local := range replacements {
		newMD = strings.ReplaceAll(newMD, orig, local)
	}
	if newMD == p.bodyMarkdown {
		return nil
	}

	if r.dryRun {
		r.log.Info("would-rewrite", "table", p.table, "id", p.id, "replacements", len(replacements))
		return nil
	}

	newHTML, err := markdown.Render(newMD)
	if err != nil {
		return fmt.Errorf("render markdown: %w", err)
	}
	sql := fmt.Sprintf(`UPDATE %s SET body_markdown = $2, body_html = $3 WHERE id = $1`, p.table)
	if _, err := r.pool.Exec(ctx, sql, p.id, newMD, newHTML); err != nil {
		return fmt.Errorf("update: %w", err)
	}
	r.log.Info("rewrote", "table", p.table, "id", p.id, "replacements", len(replacements))
	return nil
}

func (r *rewriter) fetchOrCached(ctx context.Context, rawURL string) (string, error) {
	if local, ok := r.cache[rawURL]; ok {
		return local, nil
	}
	u, err := url.Parse(rawURL)
	if err != nil {
		r.cache[rawURL] = ""
		return "", fmt.Errorf("parse: %w", err)
	}
	host := strings.ToLower(u.Hostname())

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		r.cache[rawURL] = ""
		return "", err
	}
	if hostsRequiringCookie[host] {
		if r.cookie == "" {
			r.skipped++
			r.cache[rawURL] = ""
			r.log.Info("skipping authed host (no SO_TEAMS_COOKIE)", "url", rawURL)
			return "", nil
		}
		req.Header.Set("Cookie", r.cookie)
	}
	req.Header.Set("User-Agent", "heapoverflow-mediarewrite/1.0")

	resp, err := r.client.Do(req)
	if err != nil {
		r.cache[rawURL] = ""
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		r.cache[rawURL] = ""
		return "", fmt.Errorf("status %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, uploads.MaxImageBytes+1))
	if err != nil {
		r.cache[rawURL] = ""
		return "", err
	}

	res, err := r.store.SaveBytes(body)
	if err != nil {
		r.cache[rawURL] = ""
		return "", err
	}
	r.cache[rawURL] = res.URL
	r.downloaded++
	return res.URL, nil
}

