// classifyDryRun records whether a URL would have been fetched, skipped
// (auth required, no cookie), or attempted publicly — without doing any I/O.
func (r *rewriter) classifyDryRun(rawURL string) {
	if _, ok := r.cache[rawURL]; ok {
		return
	}
	r.cache[rawURL] = "" // mark seen
	u, err := url.Parse(rawURL)
	if err != nil {
		r.failed++
		return
	}
	host := strings.ToLower(u.Hostname())
	if hostsRequiringCookie[host] && r.cookie == "" {
		r.skipped++
		return
	}
	r.downloaded++ // would-download
}

