		params.UserID, params.Title, params.BodyMarkdown, params.BodyHTML).
		Scan(&q.ID, &q.UserID, &q.Title, &q.BodyMarkdown, &q.BodyHTML,
			&q.IsAnswered, &q.IsDeleted, &q.IsObsolete, &q.ViewCount, &q.Score,
