		UPDATE questions SET title=$2, body_markdown=$3, body_html=$4, updated_at=NOW()
		WHERE id=$1`, params.ID, params.Title, params.BodyMarkdown, params.BodyHTML); err != nil {
		return nil, fmt.Errorf("update question: %w", err)
