	if err != nil {
		return nil, fmt.Errorf("create question: %w", err)
	}
	if err := p.setQuestionTags(ctx, q.ID, params.Tags); err != nil {
		return nil, err
	}
	q.Tags = params.Tags
	return &q, nil
}

func (p *Postgres) UpdateQuestion(ctx context.Context, params UpdateQuestionParams) (*Question, error) {
	if _, err := p.db.Exec(ctx, `
