                <button class="btn" type="submit" [disabled]="(answerCommentText[a.ID] || '').length < 10">Comment</button>
              </form>
            </div>
          </div>
        }

        <h2>Your Answer</h2>
        <form class="answer-form" (submit)="postAnswer($event)">
          <app-markdown-editor
            [(ngModel)]="newAnswer"
            name="answer"
            [rows]="8"
            placeholder="Write your answer in Markdown (min 20 chars)…"
          />
          <button class="btn primary" type="submit" [disabled]="newAnswer.length < 20">Post answer</button>
        </form>
      </article>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .post { display: grid; grid-template-columns: 60px 1fr; gap: 1rem; padding: 1.5rem 0; border-bottom: 1px solid #eef1f4; }
    .post.answer.accepted { background: #f0f9ee; padding-left: 1rem; padding-right: 1rem; border-left: 4px solid #1a7f37; border-radius: 6px; }
    .vote { display: flex; flex-direction: column; align-items: center; gap: .25rem; font-weight: 600; }
    .vote button { background: none; border: 1px solid #d0d7de; border-radius: 6px; padding: .25rem .5rem; cursor: pointer; }
    .vote button:hover { background: #f3f4f6; }
    .accepted-icon { color: #1a7f37; font-size: 1.3rem; }
    .tags { margin-top: 1rem; }
    .comments { list-style: none; padding: .75rem 0 0; margin: 0; font-size: 13px; border-top: 1px solid #eef1f4; }
    .comments li { padding: .25rem 0; }
    .comment-form { display: flex; gap: .5rem; margin-top: .75rem; }
    .comment-form input { flex: 1; }
    .answer-form textarea { margin-bottom: .5rem; }
    h2 { margin: 1.5rem 0 .5rem; }
  `],
})
export class QuestionDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(ApiService);
  private auth = inject(AuthService);
  private sanitizer = inject(DomSanitizer);

  readonly q = signal<Question | null>(null);
  readonly loading = signal(true);
  newAnswer = '';
  newQuestionComment = '';
  answerCommentText: Record<number, string> = {};

  ngOnInit() {
    this.route.paramMap.subscribe((p) => {
      const id = Number(p.get('id'));
      if (id) this.load(id);
    });
  }

  private load(id: number) {
    this.loading.set(true);
    this.api.getQuestion(id).subscribe({
      next: (q) => {
        this.q.set(q);
        this.loading.set(false);
      },
      error: () => {
        this.q.set(null);
        this.loading.set(false);
      },
    });
  }

  renderHTML(html: string): SafeHtml {
    // Backend already sanitizes HTML via goldmark (raw HTML in markdown is escaped).
    return this.sanitizer.bypassSecurityTrustHtml(html);
  }

  isQuestionOwner(): boolean {
    const u = this.auth.user();
    const q = this.q();
    return !!u && !!q && u.ID === q.UserID;
  }

  vote(kind: 'question' | 'answer', id: number, type: 1 | -1) {
    const obs = kind === 'question' ? this.api.voteQuestion(id, type) : this.api.voteAnswer(id, type);
    obs.subscribe({ next: () => this.q() && this.load(this.q()!.ID) });
  }

  accept(answerId: number) {
    this.api.acceptAnswer(answerId).subscribe({ next: () => this.q() && this.load(this.q()!.ID) });
  }

  postAnswer(e: Event) {
    e.preventDefault();
    const q = this.q();
    if (!q || this.newAnswer.length < 20) return;
    this.api.createAnswer(q.ID, this.newAnswer).subscribe({
      next: () => {
        this.newAnswer = '';
        this.load(q.ID);
      },
    });
  }

  addQuestionComment(e: Event) {
    e.preventDefault();
    const q = this.q();
    if (!q || this.newQuestionComment.length < 10) return;
    this.api.createQuestionComment(q.ID, this.newQuestionComment).subscribe({
      next: () => {
        this.newQuestionComment = '';
        this.load(q.ID);
      },
    });
  }

  addAnswerComment(e: Event, a: Answer) {
    e.preventDefault();
    const text = this.answerCommentText[a.ID] || '';
    if (text.length < 10) return;
    this.api.createAnswerComment(a.ID, text).subscribe({
      next: () => {
        this.answerCommentText[a.ID] = '';
        if (this.q()) this.load(this.q()!.ID);
      },
    });
  }
}

