package importer

import (
	"context"
	"encoding/json"
	"fmt"
	"html"
	"log/slog"
	"os"
	"path/filepath"
	"time"

	"github.com/immuta/heapoverflow/internal/markdown"
	"github.com/immuta/heapoverflow/internal/store"
)

// unescape decodes HTML entities embedded in the SO Teams export (e.g.
// "&#39;" → "'"). Plain-text fields in the export are pre-encoded and
// would otherwise render literally in the UI.
func unescape(s string) string { return html.UnescapeString(s) }

type Importer struct {
	store   store.Store
	dataDir string
	log     *slog.Logger
}

func New(s store.Store, dataDir string, log *slog.Logger) *Importer {
	return &Importer{store: s, dataDir: dataDir, log: log}
}

// deletedUserLegacyID is used as a placeholder owner for posts whose
// original author is missing from the SO export (deleted/anonymous users).
const deletedUserLegacyID = -1

func (imp *Importer) Run(ctx context.Context) error {
	imp.log.Info("ensuring deleted-user placeholder")
	if err := imp.ensureDeletedUser(ctx); err != nil {
		return fmt.Errorf("ensure deleted user: %w", err)
	}
	imp.log.Info("importing users")
	if err := imp.importUsers(ctx); err != nil {
		return fmt.Errorf("import users: %w", err)
	}
	imp.log.Info("importing tags")
	if err := imp.importTags(ctx); err != nil {
		return fmt.Errorf("import tags: %w", err)
	}
	imp.log.Info("importing questions, answers, comments")
	if err := imp.importQuestions(ctx); err != nil {
		return fmt.Errorf("import questions: %w", err)
	}
	imp.log.Info("importing articles")
	if err := imp.importArticles(ctx); err != nil {
		return fmt.Errorf("import articles: %w", err)
	}
	imp.log.Info("import complete")
	return nil
}

func (imp *Importer) ensureDeletedUser(ctx context.Context) error {
	legacy := deletedUserLegacyID
	_, err := imp.store.UpsertUserFromImport(ctx, store.UpsertUserParams{
		LegacyID:    &legacy,
		DisplayName: "[deleted user]",
		IsEmployee:  false,
		CreatedAt:   time.Unix(0, 0).UTC(),
	})
	return err
}

func ownerLegacyID(uid int) int {
	if uid == 0 {
		return deletedUserLegacyID
	}
	return uid
}

func (imp *Importer) importUsers(ctx context.Context) error {
	var users []jsonUser
	if err := imp.loadJSON("users.json", &users); err != nil {
		return err
	}
	for _, u := range users {
		legacyID := u.UserID
		accountID := u.AccountID
		displayName := unescape(u.DisplayName)
		params := store.UpsertUserParams{
			LegacyID:    &legacyID,
			UserID:      &legacyID,
			AccountID:   &accountID,
			DisplayName: displayName,
			Reputation:  u.Reputation,
			BadgeBronze: u.BadgeCounts.Bronze,
			BadgeSilver: u.BadgeCounts.Silver,
			BadgeGold:   u.BadgeCounts.Gold,
			IsEmployee:  u.IsEmployee,
			CreatedAt:   u.CreationDate.Time,
		}
		if u.ProfileImage != "" {
			params.ProfileImage = &u.ProfileImage
		}
		if u.AboutMe != "" {
			about := unescape(u.AboutMe)
			params.AboutMe = &about
		}
		if !u.LastAccessDate.IsZero() {
			t := u.LastAccessDate.Time
			params.LastAccessAt = &t
		}
		if _, err := imp.store.UpsertUserFromImport(ctx, params); err != nil {
			imp.log.Warn("upsert user failed", "user_id", u.UserID, "err", err)
		}
	}
	return nil
}

func (imp *Importer) importTags(ctx context.Context) error {
	var tags []jsonTag
	if err := imp.loadJSON("tags.json", &tags); err != nil {
		return err
	}
	for _, t := range tags {
		legacyID := t.ID
		smeIDs := make([]int, 0, len(t.SMEs.Users))
		for _, sme := range t.SMEs.Users {
			smeIDs = append(smeIDs, sme.ID)
		}
		if _, err := imp.store.UpsertTagFromImport(ctx, store.UpsertTagParams{
			LegacyID:        &legacyID,
			Name:            t.Name,
			Description:     unescape(t.Description),
			Count:           t.Count,
			IsModeratorOnly: t.IsModeratorOnly,
			IsRequired:      t.IsRequired,
			Synonyms:        t.Synonyms,
			SMELegacyIDs:    smeIDs,
		}); err != nil {
			imp.log.Warn("upsert tag failed", "name", t.Name, "err", err)
		}
	}
	return nil
}

func (imp *Importer) importQuestions(ctx context.Context) error {
	var questions []jsonQuestion
	if err := imp.loadJSON("questions_answers_comments.json", &questions); err != nil {
		return err
	}

	for _, q := range questions {
		legacyID := q.QuestionID
		title := unescape(q.Title)
		bodyMD := unescape(q.BodyMarkdown)
		bodyHTML, _ := markdown.Render(bodyMD)

		dbQ, err := imp.store.UpsertQuestionFromImport(ctx, store.UpsertQuestionParams{
			LegacyID:      &legacyID,
			UserLegacyID:  ownerLegacyID(q.Owner.UserID),
			Title:         title,
			BodyMarkdown:  bodyMD,
			BodyHTML:      bodyHTML,
			IsAnswered:    q.IsAnswered,
			IsDeleted:     q.IsDeleted,
			IsObsolete:    q.IsObsolete,
			ViewCount:     q.ViewCount,
			Score:         q.Score,
			UpVoteCount:   q.UpVoteCount,
			DownVoteCount: q.DownVoteCount,
			Tags:          q.Tags,
			CreatedAt:     q.CreationDate.Time,
			UpdatedAt:     q.LastActivityDate.Time,
		})
		if err != nil {
			imp.log.Warn("upsert question failed", "question_id", q.QuestionID, "err", err)
			continue
		}

		imp.importComments(ctx, dbQ.ID, "question", q.Comments)

		// Map answer legacy_id -> db id so we can resolve the accepted_answer pointer.
		acceptedDBID := 0
		for _, a := range q.Answers {
			aLegacyID := a.AnswerID
			aBodyMD := unescape(a.BodyMarkdown)
			aBodyHTML, _ := markdown.Render(aBodyMD)
			dbA, err := imp.store.UpsertAnswerFromImport(ctx, store.UpsertAnswerParams{
				LegacyID:         &aLegacyID,
				QuestionLegacyID: q.QuestionID,
				UserLegacyID:     ownerLegacyID(a.Owner.UserID),
				BodyMarkdown:     aBodyMD,
				BodyHTML:         aBodyHTML,
				IsAccepted:       a.IsAccepted,
				Score:            a.Score,
				UpVoteCount:      a.UpVoteCount,
				DownVoteCount:    a.DownVoteCount,
				CreatedAt:        a.CreationDate.Time,
				UpdatedAt:        a.LastActivityDate.Time,
			})
			if err != nil {
				imp.log.Warn("upsert answer failed", "answer_id", a.AnswerID, "err", err)
				continue
			}
			if a.AnswerID == q.AcceptedAnswerID {
				acceptedDBID = dbA.ID
			}
			imp.importComments(ctx, dbA.ID, "answer", a.Comments)
		}

		if acceptedDBID != 0 {
			if err := imp.store.AcceptAnswer(ctx, acceptedDBID, dbQ.ID); err != nil {
				imp.log.Warn("set accepted answer failed",
					"answer_legacy_id", q.AcceptedAnswerID, "err", err)
			}
		}
	}
	return nil
}

func (imp *Importer) importComments(ctx context.Context, postID int, postType string, comments []jsonComment) {
	for _, c := range comments {
		ownerLegacy := ownerLegacyID(c.Owner.UserID)
		owner, err := imp.store.(*store.Postgres).DB().Query(ctx,
			`SELECT id FROM users WHERE legacy_id = $1`, ownerLegacy)
		if err != nil {
			imp.log.Warn("lookup comment author failed", "user_id", c.Owner.UserID, "err", err)
			continue
		}
		var userID int
		if owner.Next() {
			if err := owner.Scan(&userID); err != nil {
				owner.Close()
				continue
			}
		}
		owner.Close()
		if userID == 0 {
			continue
		}

		bodyMD := unescape(c.BodyMarkdown)
		bodyHTML, _ := markdown.Render(bodyMD)
		if _, err := imp.store.CreateComment(ctx, store.CreateCommentParams{
			UserID:       userID,
			PostID:       postID,
			PostType:     postType,
			BodyMarkdown: bodyMD,
			BodyHTML:     bodyHTML,
		}); err != nil {
			imp.log.Warn("create comment failed", "post_id", postID, "err", err)
		}
	}
}

func (imp *Importer) importArticles(ctx context.Context) error {
	var articles []jsonArticle
	if err := imp.loadJSON("articles.json", &articles); err != nil {
		return err
	}
	for _, a := range articles {
		legacyID := a.ArticleID
		title := unescape(a.Title)
		bodyMD := unescape(a.BodyMarkdown)
		bodyHTML, _ := markdown.Render(bodyMD)
		if _, err := imp.store.UpsertArticleFromImport(ctx, store.UpsertArticleParams{
			LegacyID:     &legacyID,
			UserLegacyID: ownerLegacyID(a.Owner.UserID),
			Title:        title,
			BodyMarkdown: bodyMD,
			BodyHTML:     bodyHTML,
			ArticleType:  a.ArticleType,
			ViewCount:    a.ViewCount,
			Score:        a.Score,
			Tags:         a.Tags,
			CreatedAt:    a.CreationDate.Time,
			UpdatedAt:    a.LastActivityDate.Time,
		}); err != nil {
			imp.log.Warn("upsert article failed", "article_id", a.ArticleID, "err", err)
		}
	}
	return nil
}

func (imp *Importer) loadJSON(filename string, v any) error {
	path := filepath.Join(imp.dataDir, filename)
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()
	if err := json.NewDecoder(f).Decode(v); err != nil {
		return fmt.Errorf("decode %s: %w", path, err)
	}
	return nil
}

import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { Question } from '../../models';

@Component({
  selector: 'app-question-list',
  standalone: true,
  imports: [CommonModule, RouterLink, DatePipe],
  template: `
    <header class="head">
      <h1>Questions</h1>
      <a routerLink="/questions/ask" class="btn primary">Ask question</a>
    </header>

    <div class="tabs">
      @for (s of sorts; track s.id) {
        <button
          class="tab"
          [class.active]="sort() === s.id"
          (click)="setSort(s.id)">{{ s.label }}</button>
      }
    </div>

    @if (loading()) {
      <p class="muted">Loading…</p>
    } @else if (error()) {
      <p class="error">{{ error() }}</p>
    } @else if (!questions().length) {
      <p>No questions yet.</p>
    } @else {
      <ul class="cards">
        @for (q of questions(); track q.ID) {
          <li class="card">
            <div class="stats">
              <span><strong>{{ q.Score }}</strong> votes</span>
              <span [class.answered]="q.IsAnswered">
                <strong>{{ q.AnswerCount }}</strong> answers
              </span>
              <span><strong>{{ q.ViewCount }}</strong> views</span>
            </div>
            <div class="body">
              <a class="title" [routerLink]="['/questions', q.ID]">{{ q.Title }}</a>
              <div class="tags">
                @for (t of q.Tags; track t) {
                  <a class="tag-chip" [routerLink]="['/tags', t]">{{ t }}</a>
                }
              </div>
              <div class="meta muted">
                asked {{ q.CreatedAt | date:'mediumDate' }}
                @if (q.Owner) { by <a [routerLink]="['/users', q.Owner.ID]">{{ q.Owner.DisplayName }}</a> }
              </div>
            </div>
          </li>
        }
      </ul>

      <nav class="pager">
        <button class="btn" [disabled]="page() <= 1" (click)="setPage(page() - 1)">‹ Prev</button>
        <span class="muted">Page {{ page() }} of {{ totalPages() }} ({{ total() }} total)</span>
        <button class="btn" [disabled]="page() >= totalPages()" (click)="setPage(page() + 1)">Next ›</button>
      </nav>
    }
  `,
  styles: [`
    .head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
    h1 { margin: 0; }
    .tabs { display: flex; gap: .25rem; margin-bottom: 1rem; border-bottom: 1px solid #d0d7de; }
    .tab { background: none; border: 0; padding: .5rem 1rem; cursor: pointer; font-size: 14px; color: #57606a; border-bottom: 2px solid transparent; }
    .tab:hover { color: #1f2328; }
    .tab.active { color: #1f2328; border-bottom-color: #1f6feb; font-weight: 600; }
    .cards { list-style: none; padding: 0; margin: 0; }
    .card { display: grid; grid-template-columns: 120px 1fr; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #eef1f4; }
    .stats { display: flex; flex-direction: column; gap: .25rem; color: #57606a; font-size: 13px; text-align: right; }
    .stats .answered { color: #1a7f37; font-weight: 600; }
    .title { font-size: 17px; font-weight: 500; }
    .tags { margin: .35rem 0; }
    .meta { margin-top: .25rem; }
    .pager { display: flex; justify-content: center; align-items: center; gap: 1rem; margin-top: 1.5rem; }
    .error { color: #cf222e; }
  `],
})
export class QuestionListComponent implements OnInit {
  private api = inject(ApiService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);

  readonly sorts = [
    { id: 'newest', label: 'Newest' },
    { id: 'active', label: 'Active' },
    { id: 'votes', label: 'Votes' },
    { id: 'unanswered', label: 'Unanswered' },
  ];

  readonly questions = signal<Question[]>([]);
  readonly total = signal(0);
  readonly page = signal(1);
  readonly sort = signal('newest');
  readonly loading = signal(true);
  readonly error = signal('');
  readonly tag = signal<string | undefined>(undefined);
  readonly totalPages = () => Math.max(1, Math.ceil(this.total() / 20));

  ngOnInit() {
    this.route.queryParamMap.subscribe((qp) => {
      this.page.set(Number(qp.get('page') || '1'));
      this.sort.set(qp.get('sort') || 'newest');
      this.tag.set(qp.get('tag') || undefined);
      this.reload();
    });
  }

  setSort(s: string) {
    this.router.navigate([], { queryParams: { sort: s, page: 1, tag: this.tag() }, queryParamsHandling: 'merge' });
  }

  setPage(p: number) {
    this.router.navigate([], { queryParams: { page: p }, queryParamsHandling: 'merge' });
  }

  private reload() {
    this.loading.set(true);
    this.error.set('');
    this.api
      .listQuestions({ page: this.page(), sort: this.sort(), tag: this.tag() })
      .subscribe({
        next: (res) => {
          this.questions.set(res.questions || []);
          this.total.set(res.total);
          this.loading.set(false);
        },
        error: (err) => {
          this.error.set('Failed to load questions');
          this.loading.set(false);
          console.error(err);
        },
      });
  }
}

