/*
 * Theme tokens. Components consume var(--name) so a `.dark` class on the
 * document root flips the whole UI without per-component changes.
 */
:root {
  --bg: #fafbfc;
  --bg-elev: #ffffff;
  --bg-hover: #f3f4f6;
  --bg-code: #f6f8fa;
  --bg-accent-soft: #ddf4ff;
  --bg-accent-soft-hover: #b6e3ff;
  --bg-success-soft: #f0f9ee;

  --text: #1f2328;
  --text-strong: #1a1a1a;
  --text-muted: #57606a;
  --text-link: #0969da;

  --border: #d0d7de;
  --border-subtle: #eef1f4;

  --accent: #1f6feb;
  --accent-hover: #1a5ec4;
  --accent-text: #ffffff;

  --success: #1a7f37;
  --danger: #cf222e;

  --shadow-card: 0 4px 16px rgba(0, 0, 0, 0.08);

  color-scheme: light;
}

:root.dark {
  --bg: #0d1117;
  --bg-elev: #161b22;
  --bg-hover: #1f2933;
  --bg-code: #1f2630;
  --bg-accent-soft: #0e2a47;
  --bg-accent-soft-hover: #163a63;
  --bg-success-soft: #0f2718;

  --text: #e6edf3;
  --text-strong: #f0f6fc;
  --text-muted: #8b949e;
  --text-link: #58a6ff;

  --border: #30363d;
  --border-subtle: #21262d;

  --accent: #2f81f7;
  --accent-hover: #388bfd;
  --accent-text: #ffffff;

  --success: #3fb950;
  --danger: #f85149;

  --shadow-card: 0 4px 16px rgba(0, 0, 0, 0.5);

  color-scheme: dark;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
}

a { color: var(--text-link); text-decoration: none; }
a:hover { text-decoration: underline; }

.btn {
  display: inline-block;
  padding: .5rem 1rem;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-code);
  color: var(--text);
  font-weight: 500;
  cursor: pointer;
  font-size: 14px;
  font-family: inherit;
}
.btn:hover { background: var(--bg-hover); }
.btn.primary { background: var(--accent); color: var(--accent-text); border-color: var(--accent); }
.btn.primary:hover { background: var(--accent-hover); }
.btn.danger { color: var(--danger); }
.btn:disabled { opacity: .55; cursor: not-allowed; }

input[type=text], input[type=search], textarea {
  width: 100%;
  padding: .5rem .75rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
  font-size: 14px;
  background: var(--bg-elev);
  color: var(--text);
}
textarea { resize: vertical; min-height: 120px; font-family: ui-monospace, "SF Mono", Menlo, monospace; }

.tag-chip {
  display: inline-block;
  padding: .2rem .55rem;
  background: var(--bg-accent-soft);
  color: var(--text-link);
  border-radius: 4px;
  font-size: 12px;
  margin-right: .35rem;
  text-decoration: none;
}
.tag-chip:hover { background: var(--bg-accent-soft-hover); text-decoration: none; }

.muted { color: var(--text-muted); font-size: 12px; }

.markdown-body p { margin: .6em 0; }
.markdown-body pre { background: var(--bg-code); padding: .75rem; border-radius: 6px; overflow-x: auto; }
.markdown-body code {
  background: color-mix(in srgb, var(--text-muted) 20%, transparent);
  padding: .1em .3em; border-radius: 4px; font-size: 90%;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
}
.markdown-body pre code { background: transparent; padding: 0; }
.markdown-body img { max-width: 100%; height: auto; }
.markdown-body blockquote { border-left: 4px solid var(--border); padding: 0 1rem; color: var(--text-muted); margin: 0; }
.markdown-body table { border-collapse: collapse; }
.markdown-body th, .markdown-body td { border: 1px solid var(--border); padding: .35rem .65rem; }

