import { Component, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { AuthService } from '../auth/auth.service';
import { ThemeService } from '../shared/theme.service';

@Component({
  selector: 'app-shell',
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive, FormsModule],
  template: `
    <div class="shell">
      <aside class="nav">
        <div class="brand">
          <img src="immuta-logo.png" alt="Immuta" class="logo" />
          <span>HeapOverflow</span>
        </div>
        <nav>
          <a routerLink="/questions" routerLinkActive="active">Questions</a>
          <a routerLink="/questions/ask" routerLinkActive="active">Ask</a>
          <a routerLink="/tags" routerLinkActive="active">Tags</a>
          <a routerLink="/articles" routerLinkActive="active">Articles</a>
        </nav>
      </aside>
      <main>
        <header class="topbar">
          <form (submit)="doSearch($event)" class="search">
            <input
              type="search"
              placeholder="Search questions and articles…"
              [(ngModel)]="searchQuery"
              name="q"
            />
          </form>
          <button
            type="button"
            class="theme-toggle"
            (click)="theme.toggle()"
            [attr.title]="theme.theme() === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'"
            [attr.aria-label]="theme.theme() === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'"
          >
            {{ theme.theme() === 'dark' ? '☀️' : '🌙' }}
          </button>
          @if (auth.user(); as u) {
          <div class="me">
            <a [routerLink]="['/users', u.ID]" class="me-link">
              @if (u.ProfileImage) {
                <img [src]="u.ProfileImage" alt="" />
              } @else {
                <span class="avatar-placeholder">{{ u.DisplayName.charAt(0) }}</span>
              }
              <span class="name">{{ u.DisplayName }}</span>
            </a>
            <button class="logout" (click)="auth.logout()" title="Sign out">Sign out</button>
          </div>
          }
        </header>
        <section class="content">
          <router-outlet />
        </section>
      </main>
    </div>
  `,
  styles: [`
    :host { display: block; height: 100vh; }
    .shell { display: grid; grid-template-columns: 240px 1fr; height: 100%; }
    .nav {
      background: var(--bg-elev);
      border-right: 1px solid var(--border);
      display: flex; flex-direction: column;
      padding: 1.25rem 1rem;
      gap: 1rem;
    }
    .brand { display: flex; align-items: center; gap: .5rem; font-weight: 700; font-size: 1.1rem; }
    .logo { width: 24px; height: 24px; object-fit: contain; }
    nav { display: flex; flex-direction: column; gap: .25rem; flex: 1; }
    nav a {
      display: block; padding: .5rem .75rem; border-radius: 6px;
      color: var(--text); text-decoration: none; font-weight: 500;
    }
    nav a:hover { background: var(--bg-hover); text-decoration: none; }
    nav a.active { background: var(--bg-accent-soft); color: var(--text-link); }

    main { display: flex; flex-direction: column; min-width: 0; }
    .topbar {
      padding: .75rem 1.5rem;
      background: var(--bg-elev);
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      gap: 1rem;
    }
    .search { flex: 1; max-width: 480px; }

    .theme-toggle {
      background: none;
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: .35rem .55rem;
      cursor: pointer;
      font-size: 14px;
      line-height: 1;
    }
    .theme-toggle:hover { background: var(--bg-hover); }

    .me { display: flex; align-items: center; gap: .75rem; margin-left: auto; }
    .me-link { display: flex; align-items: center; gap: .5rem; color: inherit; text-decoration: none; }
    .me-link:hover { text-decoration: none; }
    .me-link:hover .name { text-decoration: underline; }
    .me img, .avatar-placeholder {
      width: 32px; height: 32px; border-radius: 50%;
      background: var(--border);
      display: inline-flex; align-items: center; justify-content: center;
      font-weight: 700; font-size: 13px; color: var(--accent-text);
    }
    .name { font-weight: 500; }
    .logout {
      font-size: 13px; background: none; border: 1px solid var(--border);
      padding: .35rem .75rem; border-radius: 6px; cursor: pointer; color: var(--text-muted);
    }
    .logout:hover { color: var(--danger); border-color: var(--danger); }

    .content { padding: 1.5rem; overflow-y: auto; flex: 1; }
  `],
})
export class ShellComponent {
  auth = inject(AuthService);
  theme = inject(ThemeService);
  private router = inject(Router);
  searchQuery = '';

  doSearch(e: Event) {
    e.preventDefault();
    const q = this.searchQuery.trim();
    if (q) this.router.navigate(['/search'], { queryParams: { q } });
  }
}

