import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ApiService } from '../../api.service';
import { AuthService } from '../../auth/auth.service';
import { Answer, Comment, Question } from '../../models';
import { MarkdownEditorComponent } from '../../shared/markdown-editor.component';

@Component({
  selector: 'app-question-detail',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule, DatePipe, MarkdownEditorComponent],
  template: `
    @if (loading()) {
      <p class="muted">Loading…</p>
    } @else if (!q()) {
      <p>Question not found.</p>
    } @else {
      <article class="question">
        <h1>{{ q()!.Title }}</h1>
        <div class="muted">
          asked {{ q()!.CreatedAt | date:'medium' }}
          @if (q()!.Owner) { by <a [routerLink]="['/users', q()!.Owner!.ID]">{{ q()!.Owner!.DisplayName }}</a> }
          · {{ q()!.ViewCount }} views
        </div>

        <div class="post">
          <div class="vote">
            <button (click)="vote('question', q()!.ID, 1)">▲</button>
            <span>{{ q()!.Score }}</span>
            <button (click)="vote('question', q()!.ID, -1)">▼</button>
          </div>
          <div class="body">
            <div class="markdown-body" [innerHTML]="renderHTML(q()!.BodyHTML)"></div>
            <div class="tags">
              @for (t of q()!.Tags; track t) {
                <a class="tag-chip" [routerLink]="['/tags', t]">{{ t }}</a>
              }
            </div>
            @if (q()!.Comments?.length) {
              <ul class="comments">
                @for (c of q()!.Comments!; track c.ID) {
                  <li>
                    <span class="markdown-body" [innerHTML]="renderHTML(c.BodyHTML)"></span>
                    <span class="muted"> — {{ c.Owner?.DisplayName }} ({{ c.CreatedAt | date:'shortDate' }})</span>
                  </li>
                }
              </ul>
            }
            <form class="comment-form" (submit)="addQuestionComment($event)">
              <input type="text" [(ngModel)]="newQuestionComment" name="qc" placeholder="Add a comment (10+ chars)…" />
              <button class="btn" type="submit" [disabled]="newQuestionComment.length < 10">Comment</button>
            </form>
          </div>
        </div>

        <h2>{{ q()!.Answers?.length ?? q()!.AnswerCount }} Answers</h2>
        @for (a of q()!.Answers || []; track a.ID) {
          <div class="post answer" [class.accepted]="a.IsAccepted">
            <div class="vote">
              <button (click)="vote('answer', a.ID, 1)">▲</button>
              <span>{{ a.Score }}</span>
              <button (click)="vote('answer', a.ID, -1)">▼</button>
              @if (a.IsAccepted) { <span class="accepted-icon" title="Accepted">✓</span> }
            </div>
            <div class="body">
              <div class="markdown-body" [innerHTML]="renderHTML(a.BodyHTML)"></div>
              <div class="muted">
                answered {{ a.CreatedAt | date:'medium' }}
                @if (a.Owner) { by <a [routerLink]="['/users', a.Owner.ID]">{{ a.Owner.DisplayName }}</a> }
              </div>
              @if (isQuestionOwner() && !a.IsAccepted) {
                <button class="btn" (click)="accept(a.ID)">Accept this answer</button>
              }
              @if (a.Comments?.length) {
                <ul class="comments">
                  @for (c of a.Comments!; track c.ID) {
                    <li>
                      <span class="markdown-body" [innerHTML]="renderHTML(c.BodyHTML)"></span>
                      <span class="muted"> — {{ c.Owner?.DisplayName }} ({{ c.CreatedAt | date:'shortDate' }})</span>
                    </li>
                  }
                </ul>
              }
              <form class="comment-form" (submit)="addAnswerComment($event, a)">
                <input type="text" [(ngModel)]="answerCommentText[a.ID]" [name]="'ac' + a.ID" placeholder="Add a comment…" />
                <button class="btn" type="submit" [disabled]="(answerCommentText[a.ID] || '').length < 10">Comment</button>
              </form>
            </div>
          </div>
        }

        <h2>Your Answer</h2>
        <form class="answer-form" (submit)="postAnswer($event)">
          <app-markdown-editor
            [(ngModel)]="newAnswer"
            name="answer"
            [rows]="8"
            placeholder="Write your answer in Markdown (min 20 chars)…"
          />
          <button class="btn primary" type="submit" [disabled]="newAnswer.length < 20">Post answer</button>
        </form>
      </article>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .post { display: grid; grid-template-columns: 60px 1fr; gap: 1rem; padding: 1.5rem 0; border-bottom: 1px solid #eef1f4; }
    .post.answer.accepted { background: #f0f9ee; padding-left: 1rem; padding-right: 1rem; border-left: 4px solid #1a7f37; border-radius: 6px; }
    .vote { display: flex; flex-direction: column; align-items: center; gap: .25rem; font-weight: 600; }
    .vote button { background: none; border: 1px solid #d0d7de; border-radius: 6px; padding: .25rem .5rem; cursor: pointer; }
    .vote button:hover { background: #f3f4f6; }
    .accepted-icon { color: #1a7f37; font-size: 1.3rem; }
    .tags { margin-top: 1rem; }
    .comments { list-style: none; padding: .75rem 0 0; margin: 0; font-size: 13px; border-top: 1px solid #eef1f4; }
    .comments li { padding: .25rem 0; }
    .comment-form { display: flex; gap: .5rem; margin-top: .75rem; }
    .comment-form input { flex: 1; }
    .answer-form textarea { margin-bottom: .5rem; }
    h2 { margin: 1.5rem 0 .5rem; }
  `],
})
export class QuestionDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(ApiService);
  private auth = inject(AuthService);
  private sanitizer = inject(DomSanitizer);

  readonly q = signal<Question | null>(null);
  readonly loading = signal(true);
  newAnswer = '';
  newQuestionComment = '';
  answerCommentText: Record<number, string> = {};

  ngOnInit() {
    this.route.paramMap.subscribe((p) => {
      const id = Number(p.get('id'));
      if (id) this.load(id);
    });
  }

  private load(id: number) {
    this.loading.set(true);
    this.api.getQuestion(id).subscribe({
      next: (q) => {
        this.q.set(q);
        this.loading.set(false);
      },
      error: () => {
        this.q.set(null);
        this.loading.set(false);
      },
    });
  }

  renderHTML(html: string): SafeHtml {
    // Backend already sanitizes HTML via goldmark (raw HTML in markdown is escaped).
    return this.sanitizer.bypassSecurityTrustHtml(html);
  }

  isQuestionOwner(): boolean {
    const u = this.auth.user();
    const q = this.q();
    return !!u && !!q && u.ID === q.UserID;
  }

  vote(kind: 'question' | 'answer', id: number, type: 1 | -1) {
    const obs = kind === 'question' ? this.api.voteQuestion(id, type) : this.api.voteAnswer(id, type);
    obs.subscribe({ next: () => this.q() && this.load(this.q()!.ID) });
  }

  accept(answerId: number) {
    this.api.acceptAnswer(answerId).subscribe({ next: () => this.q() && this.load(this.q()!.ID) });
  }

  postAnswer(e: Event) {
    e.preventDefault();
    const q = this.q();
    if (!q || this.newAnswer.length < 20) return;
    this.api.createAnswer(q.ID, this.newAnswer).subscribe({
      next: () => {
        this.newAnswer = '';
        this.load(q.ID);
      },
    });
  }

  addQuestionComment(e: Event) {
    e.preventDefault();
    const q = this.q();
    if (!q || this.newQuestionComment.length < 10) return;
    this.api.createQuestionComment(q.ID, this.newQuestionComment).subscribe({
      next: () => {
        this.newQuestionComment = '';
        this.load(q.ID);
      },
    });
  }

  addAnswerComment(e: Event, a: Answer) {
    e.preventDefault();
    const text = this.answerCommentText[a.ID] || '';
    if (text.length < 10) return;
    this.api.createAnswerComment(a.ID, text).subscribe({
      next: () => {
        this.answerCommentText[a.ID] = '';
        if (this.q()) this.load(this.q()!.ID);
      },
    });
  }
}

import { CommonModule } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { ApiService } from '../../api.service';
import { MarkdownEditorComponent } from '../../shared/markdown-editor.component';

@Component({
  selector: 'app-ask-question',
  standalone: true,
  imports: [CommonModule, FormsModule, MarkdownEditorComponent],
  template: `
    <h1>Ask a question</h1>
    <form (submit)="submit($event)" class="form">
      <label>
        Title
        <input type="text" [(ngModel)]="title" name="title" placeholder="Be specific — at least 10 characters" />
      </label>
      <label>
        Body (Markdown, min 20 chars)
        <app-markdown-editor
          [(ngModel)]="body"
          name="body"
          [rows]="12"
          placeholder="Include all the info someone would need to answer your question."
        />
      </label>
      <label>
        Tags (comma-separated, max 5)
        <input type="text" [(ngModel)]="tagsRaw" name="tags" placeholder="postgres, k8s, deployment" />
      </label>
      @if (error()) { <p class="error">{{ error() }}</p> }
      <div class="actions">
        <button class="btn primary" type="submit" [disabled]="submitting() || !canSubmit()">Post question</button>
      </div>
    </form>
  `,
  styles: [`
    h1 { margin-top: 0; }
    .form { display: flex; flex-direction: column; gap: 1rem; max-width: 720px; }
    label { display: flex; flex-direction: column; gap: .35rem; font-weight: 600; }
    label input, label textarea { font-weight: 400; }
    .actions { display: flex; justify-content: flex-end; }
    .error { color: #cf222e; }
  `],
})
export class AskQuestionComponent {
  private api = inject(ApiService);
  private router = inject(Router);

  title = '';
  body = '';
  tagsRaw = '';
  readonly submitting = signal(false);
  readonly error = signal('');

  canSubmit() {
    return this.title.length >= 10 && this.body.length >= 20;
  }

  submit(e: Event) {
    e.preventDefault();
    if (!this.canSubmit()) return;
    const tags = this.tagsRaw
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean)
      .slice(0, 5);
    this.submitting.set(true);
    this.error.set('');
    this.api.createQuestion({ title: this.title, body_markdown: this.body, tags }).subscribe({
      next: (q) => this.router.navigate(['/questions', q.ID]),
      error: (err) => {
        this.error.set(typeof err?.error?.error === 'string' ? err.error.error : 'Failed to create question');
        this.submitting.set(false);
      },
    });
  }
}

import { CommonModule } from '@angular/common';
