              score {{ r.Score | number:'1.0-3' }}
              @if (r.Tags?.length) {
                ·
                @for (t of r.Tags; track t) {
                  <span class="tag-chip">{{ t }}</span>
                }
              }
            </div>
          </li>
        }
      </ul>
    }
  `,
  styles: [`
    h1 { margin-top: 0; }
    .list { list-style: none; padding: 0; }
    .list li { padding: 1rem 0; border-bottom: 1px solid #eef1f4; }
    .list a { font-size: 16px; font-weight: 500; }
