package badges

import (
	"context"
	"strconv"
	"time"

	"github.com/immuta/heapoverflow/internal/store"
)

// defaultBadges is the static catalog. Order matters only for the public
// /badges list view.
var defaultBadges = []Badge{
	{
		Slug:        "heap-of-help",
		Name:        "Heap of Help",
		Description: "Posted your very first answer. Welcome to the bagel club 🥯",
		Tier:        TierBronze,
		Icon:        "🥯",
	},
	{
		Slug:        "he-is-rizzen",
		Name:        "He Is Rizzen",
		Description: "Posted an answer on Easter Sunday. Resurrection-grade rizz, fr fr.",
		Tier:        TierSilver,
		Icon:        "🐰",
	},
	{
		Slug:        "christmas-crackin",
		Name:        "Christmas Crackin'",
		Description: "Cracked an answer on Christmas Day instead of opening presents. We see you.",
		Tier:        TierSilver,
		Icon:        "🎄",
	},
	{
		Slug:        "spooky-slayer",
		Name:        "Spooky Slayer",
		Description: "Answered a question on Halloween. Boo who? You, slaying.",
		Tier:        TierBronze,
		Icon:        "🎃",
	},
	{
		Slug:        "brain-rot",
		Name:        "Brain Rot",
		Description: "Posted an answer between 2 and 5 AM UTC. Go touch grass.",
		Tier:        TierBronze,
		Icon:        "🤓",
	},
	{
		Slug:        "necromancer",
		Name:        "Necromancer",
		Description: "Answered a question more than 180 days after it was asked. Sus.",
		Tier:        TierSilver,
		Icon:        "👻",
	},
}

// checker pairs an event type with the function that evaluates it.
type registeredChecker struct {
	on EventType
	fn Checker
}

// defaultCheckers is the live list. Each entry says "when X happens,
// evaluate Y". Order is irrelevant — every matching checker runs.
var defaultCheckers = []registeredChecker{
	{EventAnswerCreated, checkHeapOfHelp},
	{EventAnswerCreated, checkHeIsRizzen},
	{EventAnswerCreated, checkChristmas},
	{EventAnswerCreated, checkHalloween},
	{EventAnswerCreated, checkBrainRot},
	{EventAnswerCreated, checkNecromancer},
}

// checkHeapOfHelp — user's first answer ever. We don't have a count
// pre-baked, so query the answers table. context_key is empty (one-shot).
func checkHeapOfHelp(ctx context.Context, s store.Store, ev Event) *Award {
	answers, err := s.ListAnswersByQuestion(ctx, ev.QuestionID)
	if err != nil {
		return nil
	}
	// First, locate this user's earliest answer across the whole site by
	// asking the store via a custom query through the Postgres concrete
	// type. To stay store-agnostic we use a simple heuristic: if the
	// user has only this single answer so far in this question and no
	// earlier ones overall, award it. Since we don't have a
	// count-answers-by-user store method, defer to a SQL query through
	// the underlying DB exposed by *store.Postgres.DB().
	p, ok := s.(*store.Postgres)
	if !ok {
		return nil
	}
	var total int
	if err := p.DB().QueryRow(ctx,
		`SELECT COUNT(*) FROM answers WHERE user_id = $1`, ev.UserID,
	).Scan(&total); err != nil {
		return nil
	}
	_ = answers
	if total != 1 {
		return nil
	}
	return &Award{Slug: "heap-of-help"}
}

func checkHeIsRizzen(_ context.Context, _ store.Store, ev Event) *Award {
	y, m, d := ev.At.UTC().Date()
	em, ed := easterSunday(y)
	if int(m) != em || d != ed {
		return nil
	}
	return &Award{Slug: "he-is-rizzen", ContextKey: strconv.Itoa(y)}
}

func checkChristmas(_ context.Context, _ store.Store, ev Event) *Award {
	y, m, d := ev.At.UTC().Date()
	if m != time.December || d != 25 {
		return nil
	}
	return &Award{Slug: "christmas-crackin", ContextKey: strconv.Itoa(y)}
}

func checkHalloween(_ context.Context, _ store.Store, ev Event) *Award {
	y, m, d := ev.At.UTC().Date()
	if m != time.October || d != 31 {
		return nil
	}
	return &Award{Slug: "spooky-slayer", ContextKey: strconv.Itoa(y)}
}

func checkBrainRot(_ context.Context, _ store.Store, ev Event) *Award {
	h := ev.At.UTC().Hour()
	if h < 2 || h >= 5 {
		return nil
	}
	// One award per UTC date so dedicated insomniacs can re-earn.
	return &Award{Slug: "brain-rot", ContextKey: ev.At.UTC().Format("2006-01-02")}
}

func checkNecromancer(_ context.Context, _ store.Store, ev Event) *Award {
	if ev.QuestionCreatedAt.IsZero() {
		return nil
	}
	if ev.At.Sub(ev.QuestionCreatedAt) < 180*24*time.Hour {
		return nil
	}
	return &Award{Slug: "necromancer", ContextKey: strconv.Itoa(ev.AnswerID)}
}

// easterSunday returns the (month, day) of Western Easter for the given
// year using the Anonymous Gregorian algorithm (Meeus/Jones/Butcher).
func easterSunday(year int) (month int, day int) {
	a := year % 19
	b := year / 100
	c := year % 100
	d := b / 4
	e := b % 4
	f := (b + 8) / 25
	g := (b - f + 1) / 3
	h := (19*a + b - d - g + 15) % 30
	i := c / 4
	k := c % 4
	l := (32 + 2*e + 2*i - h - k) % 7
	m := (a + 11*h + 22*l) / 451
	mo := (h + l - 7*m + 114) / 31
	da := ((h + l - 7*m + 114) % 31) + 1
	return mo, da
}

