// Package badges defines the badge engine: a small in-process registry of
// Checker functions that inspect events (e.g. "an answer was created") and
// decide whether to award a badge to the actor.
//
// Awards are deduplicated by (user_id, badge_id, context_key). The context
// key lets us award the same badge to the same user multiple times so long
// as it's for a meaningfully different occasion (e.g. an Easter badge once
// per year — context_key = "2026").
package badges

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/immuta/heapoverflow/internal/store"
)

// Tier corresponds to the badges.tier SMALLINT column.
type Tier int

const (
	TierBronze Tier = 1
	TierSilver Tier = 2
	TierGold   Tier = 3
)

// Badge is the static definition that lives in the badges table.
type Badge struct {
	Slug        string
	Name        string
	Description string
	Tier        Tier
	Icon        string
}

// EventType identifies the kind of action that occurred.
type EventType string

const (
	EventAnswerCreated EventType = "answer_created"
)

// Event is the payload passed to every Checker on every event.
type Event struct {
	Type EventType

	// Actor / target.
	UserID     int
	AnswerID   int
	QuestionID int

	// At is the wall-clock time of the event (the answer's created_at when
	// fired live, or whatever we read off the row during backfill).
	At time.Time

	// Optional fields populated for some event types.
	QuestionCreatedAt time.Time
}

// Award is a positive result from a Checker — "yes, award this badge to
// this user, dedup with this key".
type Award struct {
	Slug       string
	ContextKey string
}

// Checker inspects an event and either returns an award or nil.
type Checker func(ctx context.Context, s store.Store, ev Event) *Award

// AwardedBadge is the row returned to API callers — denormalized badge def
// + the user's award metadata.
type AwardedBadge struct {
	Badge      Badge     `json:"badge"`
	AwardedAt  time.Time `json:"awarded_at"`
	ContextKey string    `json:"context_key,omitempty"`
}

// Engine ties badge definitions to checkers and persists awards.
type Engine struct {
	pool     dbPool
	log      *slog.Logger
	defs     []Badge
	checkers map[EventType][]Checker
	slugToID map[string]int // populated by Seed()
}

// dbPool is the small interface Engine needs from pgxpool.Pool.
type dbPool interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconnCommandTag, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

// pgconnCommandTag is a thin alias so we don't drag pgconn into the
// interface signature.
type pgconnCommandTag = interface {
	String() string
	RowsAffected() int64
}

// NewEngine creates an engine. Call Seed() once at startup to persist the
// badge definitions before firing any events.
func NewEngine(pool dbPool, log *slog.Logger) *Engine {
	e := &Engine{
		pool:     pool,
		log:      log,
		defs:     defaultBadges,
		checkers: map[EventType][]Checker{},
		slugToID: map[string]int{},
	}
	for _, c := range defaultCheckers {
		e.checkers[c.on] = append(e.checkers[c.on], c.fn)
	}
	return e
}

// Seed upserts all known badge definitions into the badges table and caches
// their primary keys.
func (e *Engine) Seed(ctx context.Context) error {
	for _, b := range e.defs {
		var id int
		err := e.pool.QueryRow(ctx, `
			INSERT INTO badges (slug, name, description, tier, icon)
			VALUES ($1, $2, $3, $4, $5)
			ON CONFLICT (slug) DO UPDATE SET
				name = EXCLUDED.name,
				description = EXCLUDED.description,
				tier = EXCLUDED.tier,
				icon = EXCLUDED.icon
			RETURNING id
		`, b.Slug, b.Name, b.Description, int(b.Tier), b.Icon).Scan(&id)
		if err != nil {
			return fmt.Errorf("seed badge %q: %w", b.Slug, err)
		}
		e.slugToID[b.Slug] = id
	}
	return nil
}

// Fire evaluates every checker registered for ev.Type and awards any
// matching badges. Errors from individual awards are logged but not
// returned — badges are best-effort and must not break the user-facing flow.
func (e *Engine) Fire(ctx context.Context, s store.Store, ev Event) {
	for _, c := range e.checkers[ev.Type] {
		award := c(ctx, s, ev)
		if award == nil {
			continue
		}
		if err := e.persist(ctx, ev.UserID, *award); err != nil {
			e.log.Warn("badge award failed", "slug", award.Slug, "user_id", ev.UserID, "err", err)
		}
	}
}

func (e *Engine) persist(ctx context.Context, userID int, a Award) error {
	id, ok := e.slugToID[a.Slug]
	if !ok {
		return fmt.Errorf("unknown badge slug %q (forgot to Seed?)", a.Slug)
	}
	_, err := e.pool.Exec(ctx, `
		INSERT INTO user_badges (user_id, badge_id, context_key)
		VALUES ($1, $2, $3)
		ON CONFLICT (user_id, badge_id, context_key) DO NOTHING
	`, userID, id, a.ContextKey)
	return err
}

// ListForUser returns every badge a user has earned, newest first.
func (e *Engine) ListForUser(ctx context.Context, userID int) ([]AwardedBadge, error) {
	rows, err := e.pool.Query(ctx, `
		SELECT b.slug, b.name, b.description, b.tier, b.icon,
		       ub.awarded_at, ub.context_key
		FROM user_badges ub
		JOIN badges b ON b.id = ub.badge_id
		WHERE ub.user_id = $1
		ORDER BY ub.awarded_at DESC
	`, userID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, nil
		}
		return nil, fmt.Errorf("list badges: %w", err)
	}
	defer rows.Close()

	var out []AwardedBadge
	for rows.Next() {
		var ab AwardedBadge
		var tier int
		if err := rows.Scan(
			&ab.Badge.Slug, &ab.Badge.Name, &ab.Badge.Description,
			&tier, &ab.Badge.Icon, &ab.AwardedAt, &ab.ContextKey,
		); err != nil {
			return nil, fmt.Errorf("scan badge: %w", err)
		}
		ab.Badge.Tier = Tier(tier)
		out = append(out, ab)
	}
	return out, rows.Err()
}

// Definitions returns the complete badge catalog (regardless of who has
// earned what). Useful for listing all available badges in the UI.
func (e *Engine) Definitions() []Badge {
	return append([]Badge(nil), e.defs...)
}

