// awardbadges replays the badge engine across every existing answer in
// the DB. Idempotent — awards are deduplicated by
// (user_id, badge_id, context_key) so re-running is safe.
//
// Usage:
//
//	DATABASE_URL=postgres://... go run ./cmd/awardbadges
package main

import (
	"context"
	"log/slog"
	"os"

	"github.com/immuta/heapoverflow/internal/badges"
	"github.com/immuta/heapoverflow/internal/db"
	"github.com/immuta/heapoverflow/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stdout, nil))

	databaseURL := os.Getenv("DATABASE_URL")
	if databaseURL == "" {
		log.Error("DATABASE_URL is required")
		os.Exit(1)
	}

	ctx := context.Background()
	pool, err := db.Connect(ctx, databaseURL)
	if err != nil {
		log.Error("connect db", "err", err)
		os.Exit(1)
	}
	defer pool.Close()

	s := store.New(pool)

	engine := badges.NewEngine(pool, log)
	if err := engine.Seed(ctx); err != nil {
		log.Error("seed badges", "err", err)
		os.Exit(1)
	}

	rows, err := pool.Query(ctx, `
		SELECT a.id, a.question_id, a.user_id, a.created_at, q.created_at
		FROM answers a
		JOIN questions q ON q.id = a.question_id
		ORDER BY a.created_at ASC
	`)
	if err != nil {
		log.Error("query answers", "err", err)
		os.Exit(1)
	}
	defer rows.Close()

	var processed int
	for rows.Next() {
		var ev badges.Event
		ev.Type = badges.EventAnswerCreated
		if err := rows.Scan(&ev.AnswerID, &ev.QuestionID, &ev.UserID, &ev.At, &ev.QuestionCreatedAt); err != nil {
			log.Warn("scan failed", "err", err)
			continue
		}
		engine.Fire(ctx, s, ev)
		processed++
	}
	if err := rows.Err(); err != nil {
		log.Error("rows error", "err", err)
		os.Exit(1)
	}

	var awarded int
	if err := pool.QueryRow(ctx, `SELECT COUNT(*) FROM user_badges`).Scan(&awarded); err != nil {
		log.Warn("count awards failed", "err", err)
	}
	log.Info("backfill complete", "answers_processed", processed, "total_awards", awarded)
}

