import { CommonModule, DatePipe } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { ApiService } from '../../api.service';
import { AuthService } from '../../auth/auth.service';
import { AwardedBadge, User } from '../../models';

@Component({
  selector: 'app-user-profile',
  standalone: true,
  imports: [CommonModule, FormsModule, DatePipe],
  template: `
    @if (user(); as u) {
      <header class="head">
        @if (u.ProfileImage) {
          <img [src]="u.ProfileImage" alt="" />
        } @else {
          <span class="avatar-placeholder">{{ u.DisplayName.charAt(0) }}</span>
        }
        <div>
          <h1>{{ u.DisplayName }}</h1>
          <p class="muted">
            Reputation: <strong>{{ u.Reputation }}</strong> ·
            🥉 {{ u.BadgeBronze }} 🥈 {{ u.BadgeSilver }} 🥇 {{ u.BadgeGold }}
            · Joined {{ u.CreatedAt | date:'mediumDate' }}
          </p>
        </div>
      </header>

      @if (badges().length) {
        <section class="badges">
          <h2>Badges <span class="muted">({{ badges().length }})</span></h2>
          <div class="badge-grid">
            @for (b of badges(); track b.badge.Slug + b.context_key) {
              <div class="badge" [class.tier-1]="b.badge.Tier === 1" [class.tier-2]="b.badge.Tier === 2" [class.tier-3]="b.badge.Tier === 3"
                   [title]="b.badge.Description + ' — earned ' + (b.awarded_at | date:'mediumDate')">
                <span class="icon">{{ b.badge.Icon }}</span>
                <span class="name">{{ b.badge.Name }}</span>
              </div>
            }
          </div>
        </section>
      }

      @if (u.AboutMe) {
        <section class="about">
          <h2>About</h2>
          <div class="markdown-body" [innerHTML]="u.AboutMe"></div>
        </section>
      }

      @if (canEdit()) {
        <section class="edit">
          <h2>Edit your profile</h2>
          <form (submit)="save($event)">
            <label>
              Display name
              <input type="text" [(ngModel)]="editName" name="name" />
            </label>
            <label>
              About me (HTML)
              <textarea [(ngModel)]="editAbout" name="about" rows="6"></textarea>
            </label>
            <button class="btn primary" type="submit">Save</button>
            @if (saved()) { <span class="muted"> Saved ✓</span> }
          </form>
        </section>
      }
    } @else if (loading()) {
      <p class="muted">Loading…</p>
    } @else {
      <p>User not found.</p>
    }
  `,
  styles: [`
    .head { display: flex; align-items: center; gap: 1rem; margin-bottom: 1.5rem; }
    .head img, .avatar-placeholder { width: 96px; height: 96px; border-radius: 50%; background: var(--border); display: inline-flex; align-items: center; justify-content: center; color: var(--accent-text); font-size: 2rem; font-weight: 700; }
    h1 { margin: 0; }
    section { margin-top: 2rem; }
    label { display: flex; flex-direction: column; gap: .25rem; margin-bottom: 1rem; max-width: 600px; }

    .badge-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: .75rem; }
    .badge {
      display: flex; align-items: center; gap: .65rem;
      padding: .65rem .85rem;
      border: 1px solid var(--border);
      border-left-width: 4px;
      background: var(--bg-elev);
      border-radius: 6px;
      cursor: help;
    }
    .badge .icon { font-size: 1.5rem; line-height: 1; }
    .badge .name { font-weight: 600; font-size: 13px; }
    .badge.tier-1 { border-left-color: #cd7f32; }
    .badge.tier-2 { border-left-color: #c0c0c0; }
    .badge.tier-3 { border-left-color: #ffd700; }
  `],
})
export class UserProfileComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(ApiService);
  auth = inject(AuthService);

  readonly user = signal<User | null>(null);
  readonly loading = signal(true);
  readonly saved = signal(false);
  editName = '';
  editAbout = '';

  ngOnInit() {
    this.route.paramMap.subscribe((p) => {
      const id = Number(p.get('id'));
      if (!id) return;
      this.loading.set(true);
      this.api.getUser(id).subscribe({
        next: (u) => {
          this.user.set(u);
          this.editName = u.DisplayName;
          this.editAbout = u.AboutMe || '';
          this.loading.set(false);
        },
        error: () => {
          this.user.set(null);
          this.loading.set(false);
        },
      });
    });
  }

  canEdit(): boolean {
    const me = this.auth.user();
    const u = this.user();
    return !!me && !!u && me.ID === u.ID;
  }

  save(e: Event) {
    e.preventDefault();
    this.saved.set(false);
    this.api.updateMe({ display_name: this.editName, about_me: this.editAbout || null }).subscribe({
      next: (u) => {
        this.user.set(u);
        this.auth.setUser(u);
        this.saved.set(true);
      },
    });
  }
}

